#ifdef SS_TOUCH
// Элементы сенсорного управления. Каждый можно двигать, менять размер и скрывать (редактор раскладки).
enum { TB_FIRE, TB_JUMP, TB_RELOAD, TB_SWAP, TB_SCOPE, TB_PLANT, TB_BUY, TB_PAUSE, TB_STICK, TB_FIRE2, TB_SCORE, TB_COUNT };
struct TBtn { float cx, cy, r; };
struct TLay { float x, y, s; bool on; };   // x,y - доли экрана, s - множитель размера
static const char* TLABEL[TB_COUNT] = { "FIRE", "JUMP", "R", "SWAP", "SCOPE", "PLANT", "BUY", "II", "MOVE", "FIRE 2", "TAB" };
static const float TBASE[TB_COUNT]  = { 92, 54, 48, 46, 46, 62, 44, 38, 95, 78, 38 };
static TLay  tLay[TB_COUNT];
static float tOpacity = 0.7f;        // 0.2 .. 1.0
static float gLookSens = 0.57f;      // 0..1  ->  множитель обзора 0.4 .. 2.5
static bool  editingLayout = false;
static int   tSel = -1, tDrag = -1;
static Vector2 tDragOff = { 0, 0 };
static bool  edPrevDown = false;

struct TouchSlot { int id; int role; float lx, ly; };   // role: 0 игнор, 1 стик, 2 обзор, 10+i кнопка i
static TouchSlot tSlots[16];
static int  tSlotN = 0;
static bool tVis[TB_COUNT] = {};          // что показано по ситуации (ставит основной цикл)
static bool tBtnDown[TB_COUNT] = {}, tBtnPressed[TB_COUNT] = {};
static bool tScopeOn = false;
static Vector2 tMove = { 0, 0 };          // x: вправо, y: вперёд, длина 0..1
static float tMoveMag = 0.0f;
static Vector2 tLook = { 0, 0 };          // сдвиг пальца обзора за кадр (пиксели экрана)
static bool tStickOn = false;
static Vector2 tStickK = { 0, 0 };
static Vector2 tPtr = { -1000, -1000 };   // указатель для меню (виртуальные координаты 1280x720)
static bool tPtrDown = false, tPtrPressed = false, tPtrPrev = false;

static float TUnit() { return GetScreenHeight() / 720.0f; }
static bool TEff(int i) { return tVis[i] && tLay[i].on; }

static void TouchDefaults() {
    float W = (float)GetScreenWidth(), H = (float)GetScreenHeight(), u = H / 720.0f;
    if (W < 100 || H < 100) { W = 1280; H = 720; u = 1.0f; }
    float d[TB_COUNT][2] = {
        { W - 175 * u, H - 165 * u }, { W - 345 * u, H - 95 * u }, { W - 345 * u, H - 235 * u },
        { W - 175 * u, H - 355 * u }, { W - 320 * u, H - 365 * u }, { W * 0.5f, H - 105 * u },
        { 190 * u, 56 * u }, { 62 * u, 56 * u }, { 175 * u, H - 170 * u }, { 115 * u, 300 * u }, { 300 * u, 56 * u }
    };
    for (int i = 0; i < TB_COUNT; i++) tLay[i] = TLay{ d[i][0] / W, d[i][1] / H, 1.0f, i != TB_FIRE2 };
    tOpacity = 0.7f;
}
static void TouchLayout(TBtn* b) {
    float W = (float)GetScreenWidth(), H = (float)GetScreenHeight(), u = TUnit();
    for (int i = 0; i < TB_COUNT; i++) b[i] = TBtn{ tLay[i].x * W, tLay[i].y * H, TBASE[i] * u * tLay[i].s };
}
static void TouchSave() {
    char buf[1024];
    int n = snprintf(buf, sizeof(buf), "SSCTRL 1 %d %.3f %.3f\n", (int)TB_COUNT, tOpacity, gLookSens);
    for (int i = 0; i < TB_COUNT && n > 0 && n < (int)sizeof(buf) - 80; i++)
        n += snprintf(buf + n, sizeof(buf) - n, "%.4f %.4f %.3f %d\n", tLay[i].x, tLay[i].y, tLay[i].s, tLay[i].on ? 1 : 0);
    SaveFileText("sandstrike_controls.cfg", buf);
}
static void TouchLoad() {
    char* t = LoadFileText("sandstrike_controls.cfg");
    if (!t) return;
    int ver = 0, cnt = 0, off = 0; float op = 0.7f, sens = 0.57f;
    if (sscanf(t, "SSCTRL %d %d %f %f%n", &ver, &cnt, &op, &sens, &off) == 4 && ver == 1 && (cnt == TB_COUNT || cnt == TB_COUNT - 1)) {
        TLay tmp[TB_COUNT]; for (int i = 0; i < TB_COUNT; i++) tmp[i] = tLay[i];   // новые кнопки остаются по умолчанию
        const char* p = t + off; bool ok = true;
        for (int i = 0; i < cnt; i++) {
            float x, y, s; int on, o2 = 0;
            if (sscanf(p, " %f %f %f %d%n", &x, &y, &s, &on, &o2) != 4) { ok = false; break; }
            p += o2;
            tmp[i] = TLay{ Clamp(x, 0.0f, 1.0f), Clamp(y, 0.0f, 1.0f), Clamp(s, 0.5f, 2.0f), on != 0 };
        }
        if (ok) {
            for (int i = 0; i < TB_COUNT; i++) tLay[i] = tmp[i];
            tLay[TB_PAUSE].on = true;
            tOpacity = Clamp(op, 0.2f, 1.0f);
            gLookSens = Clamp(sens, 0.0f, 1.0f);
        }
    }
    UnloadFileText(t);
}

static void TouchUpdate(bool controls) {
    tLook = { 0, 0 };
    for (int i = 0; i < TB_COUNT; i++) tBtnPressed[i] = false;
    int n = std::min(GetTouchPointCount(), 10);
    // указатель для меню = первый палец
    tPtrPrev = tPtrDown;
    if (n > 0) {
        Vector2 p = GetTouchPosition(0);
        tPtr = { (p.x - uiOffX) / uiScale, (p.y - uiOffY) / uiScale };
        tPtrDown = true;
    } else { tPtr = { -1000, -1000 }; tPtrDown = false; }
    tPtrPressed = tPtrDown && !tPtrPrev;

    int ids[10]; Vector2 pos[10];
    for (int i = 0; i < n; i++) { ids[i] = GetTouchPointId(i); pos[i] = GetTouchPosition(i); }

    // убрать отпущенные пальцы
    int k = 0;
    for (int s = 0; s < tSlotN; s++) {
        bool alive = false;
        for (int i = 0; i < n; i++) if (ids[i] == tSlots[s].id) { alive = true; break; }
        if (alive) tSlots[k++] = tSlots[s];
    }
    tSlotN = k;

    TBtn btn[TB_COUNT]; TouchLayout(btn);
    bool stickTaken = false;
    for (int s = 0; s < tSlotN; s++) if (tSlots[s].role == 1) stickTaken = true;

    // новые пальцы
    for (int i = 0; i < n && tSlotN < 16; i++) {
        bool known = false;
        for (int s = 0; s < tSlotN; s++) if (tSlots[s].id == ids[i]) { known = true; break; }
        if (known) continue;
        TouchSlot ns = { ids[i], 0, pos[i].x, pos[i].y };   // role 0 = игнор до отпускания пальца
        if (controls) {
            int hit = -1;
            for (int b = 0; b < TB_COUNT; b++) {
                if (b == TB_STICK || !TEff(b)) continue;
                float dx = pos[i].x - btn[b].cx, dy = pos[i].y - btn[b].cy, rr = btn[b].r * 1.2f;
                if (dx * dx + dy * dy <= rr * rr) { hit = b; break; }
            }
            if (hit >= 0) { ns.role = 10 + hit; tBtnPressed[hit] = true; }
            else {
                float dx = pos[i].x - btn[TB_STICK].cx, dy = pos[i].y - btn[TB_STICK].cy, rr = btn[TB_STICK].r * 1.7f;
                if (TEff(TB_STICK) && !stickTaken && dx * dx + dy * dy <= rr * rr) { ns.role = 1; stickTaken = true; }
                else if (tVis[TB_FIRE]) ns.role = 2;       // свободное место экрана = обзор
            }
        }
        tSlots[tSlotN++] = ns;
    }

    // обработка
    for (int i = 0; i < TB_COUNT; i++) tBtnDown[i] = false;
    tMove = { 0, 0 }; tMoveMag = 0.0f;
    bool stickSeen = false;
    for (int s = 0; s < tSlotN; s++) {
        TouchSlot& sl = tSlots[s];
        Vector2 p = { 0, 0 };
        for (int i = 0; i < n; i++) if (ids[i] == sl.id) p = pos[i];
        if (!controls) { sl.role = 0; continue; }
        if (sl.role == 1) {
            stickSeen = true;
            Vector2 O = { btn[TB_STICK].cx, btn[TB_STICK].cy };
            float R = btn[TB_STICK].r;
            Vector2 d = { p.x - O.x, p.y - O.y };
            float len = sqrtf(d.x * d.x + d.y * d.y);
            float m = std::min(1.0f, len / R);
            float cl = (len > R) ? R / len : 1.0f;
            tStickOn = true;
            tStickK = { O.x + d.x * cl, O.y + d.y * cl };
            if (m > 0.12f) {
                float mm = (m - 0.12f) / 0.88f;
                tMove.x = (p.x - O.x) / std::max(len, 1.0f) * mm;
                tMove.y = -(p.y - O.y) / std::max(len, 1.0f) * mm;
                tMoveMag = mm;
            }
        } else if (sl.role == 2) {
            tLook.x += p.x - sl.lx; tLook.y += p.y - sl.ly;
        } else if (sl.role >= 10) {
            tBtnDown[sl.role - 10] = true;
        }
        sl.lx = p.x; sl.ly = p.y;
    }
    if (!stickSeen) tStickOn = false;
    if (tBtnPressed[TB_SCOPE]) tScopeOn = !tScopeOn;
    if (!controls) tScopeOn = false;
}
static void DrawTouchControls() {
    TBtn btn[TB_COUNT]; TouchLayout(btn);
    float u = TUnit(), A = tOpacity / 0.7f;
    for (int i = 0; i < TB_COUNT; i++) {
        if (!TEff(i)) continue;
        Vector2 c = { btn[i].cx, btn[i].cy };
        if (i == TB_STICK) {
            Vector2 kn = tStickOn ? tStickK : c;
            DrawCircleV(c, btn[i].r, Fade(WHITE, std::min(1.0f, (tStickOn ? 0.10f : 0.07f) * A)));
            DrawCircleLines((int)c.x, (int)c.y, btn[i].r, Fade(WHITE, std::min(1.0f, (tStickOn ? 0.55f : 0.35f) * A)));
            DrawCircleV(kn, btn[i].r * 0.4f, Fade(WHITE, std::min(1.0f, (tStickOn ? 0.45f : 0.22f) * A)));
            continue;
        }
        bool on = tBtnDown[i] || (i == TB_SCOPE && tScopeOn);
        Color col = (i == TB_FIRE || i == TB_FIRE2) ? Color{ 255, 90, 60, 255 } : Color{ 255, 255, 255, 255 };
        DrawCircleV(c, btn[i].r, Fade(col, std::min(1.0f, (on ? 0.40f : 0.14f) * A)));
        DrawCircleLines((int)c.x, (int)c.y, btn[i].r, Fade(col, std::min(1.0f, 0.65f * A)));
        int fs = std::max(12, (int)(btn[i].r * (i == TB_FIRE ? 0.34f : 0.40f)));
        const char* lab = (i == TB_PLANT && ::A[gMe].team == CT) ? "DEFUSE" : TLABEL[i];
        int tw = MeasureText(lab, fs);
        DrawText(lab, (int)(c.x - tw / 2), (int)(c.y - fs / 2), fs, Fade(WHITE, std::min(1.0f, 0.9f * A)));
    }
    (void)u;
}

// ---------- редактор раскладки ----------
static bool EdBtn(Rectangle r, const char* t, int fs, bool press, Vector2 p, bool active = false) {
    bool hov = CheckCollisionPointRec(p, r);
    DrawRectangleRec(r, active ? Color{ 230, 160, 50, 240 } : Color{ 40, 44, 58, 240 });
    DrawRectangleLinesEx(r, 2, Color{ 200, 200, 210, 210 });
    int tw = MeasureText(t, fs);
    DrawText(t, (int)(r.x + (r.width - tw) / 2), (int)(r.y + (r.height - fs) / 2), fs, active ? BLACK : WHITE);
    return press && hov;
}
static void DrawLayoutEditor() {
    float W = (float)GetScreenWidth(), H = (float)GetScreenHeight(), u = H / 720.0f;
    int n = GetTouchPointCount();
    Vector2 p = (n > 0) ? GetTouchPosition(0) : Vector2{ -1000, -1000 };
    bool down = n > 0, press = down && !edPrevDown;
    edPrevDown = down;
    bool back = IsKeyPressed(KEY_BACK);

    ClearBackground(Color{ 16, 18, 26, 255 });
    for (int g = 1; g < 10; g++) DrawLine((int)(W * g / 10), 0, (int)(W * g / 10), (int)H, Color{ 255, 255, 255, 12 });
    for (int g = 1; g < 6; g++) DrawLine(0, (int)(H * g / 6), (int)W, (int)(H * g / 6), Color{ 255, 255, 255, 12 });

    TBtn b[TB_COUNT]; TouchLayout(b);

    // --- панель сверху: SAVE / RESET / прозрачность ---
    float bh = 52 * u, gap = 10 * u, y0 = 12 * u;
    float wSave = 230 * u, wReset = 150 * u, wOpT = 170 * u, wSm = 52 * u;
    float total = wSave + wReset + wOpT + 2 * wSm + 4 * gap;
    float x = (W - total) / 2;
    Rectangle rSave = { x, y0, wSave, bh };               x += wSave + gap;
    Rectangle rReset = { x, y0, wReset, bh };             x += wReset + gap;
    Rectangle rOpT = { x, y0, wOpT, bh };                 x += wOpT + gap;
    Rectangle rOpM = { x, y0, wSm, bh };                  x += wSm + gap;
    Rectangle rOpP = { x, y0, wSm, bh };

    // --- панель выбранной кнопки: - + ON/OFF ---
    Rectangle rMinus = { 0, 0, 0, 0 }, rPlus = rMinus, rOnOff = rMinus;
    bool haveSel = (tSel >= 0 && tSel < TB_COUNT);
    if (haveSel) {
        float rw = 64 * u, ow = 110 * u, h2 = 52 * u, g2 = 8 * u;
        float tot = rw * 2 + ow + g2 * 2;
        float cy = b[tSel].cy + b[tSel].r + 14 * u;
        if (cy + h2 > H - 4 * u) cy = b[tSel].cy - b[tSel].r - 14 * u - h2;
        float sx = Clamp(b[tSel].cx - tot / 2, 4 * u, W - tot - 4 * u);
        rMinus = { sx, cy, rw, h2 };
        rPlus = { sx + rw + g2, cy, rw, h2 };
        rOnOff = { sx + 2 * (rw + g2), cy, ow, h2 };
    }
    bool overUI = CheckCollisionPointRec(p, rSave) || CheckCollisionPointRec(p, rReset) || CheckCollisionPointRec(p, rOpM) ||
                  CheckCollisionPointRec(p, rOpP) || (haveSel && (CheckCollisionPointRec(p, rMinus) || CheckCollisionPointRec(p, rPlus) ||
                  (tSel != TB_PAUSE && CheckCollisionPointRec(p, rOnOff))));

    // --- выбор и перетаскивание ---
    if (press && !overUI) {
        tSel = -1; tDrag = -1;
        for (int i = TB_COUNT - 1; i >= 0; i--) {
            float dx = p.x - b[i].cx, dy = p.y - b[i].cy, rr = b[i].r * 1.1f;
            if (dx * dx + dy * dy <= rr * rr) { tSel = i; tDrag = i; tDragOff = { p.x - b[i].cx, p.y - b[i].cy }; break; }
        }
    }
    if (tDrag >= 0) {
        if (down) {
            tLay[tDrag].x = Clamp((p.x - tDragOff.x) / W, 0.02f, 0.98f);
            tLay[tDrag].y = Clamp((p.y - tDragOff.y) / H, 0.03f, 0.97f);
        } else tDrag = -1;
    }
    TouchLayout(b);

    // --- рисуем элементы ---
    for (int i = 0; i < TB_COUNT; i++) {
        float a = tLay[i].on ? 1.0f : 0.35f;
        Vector2 c = { b[i].cx, b[i].cy };
        Color col = (i == TB_FIRE || i == TB_FIRE2) ? Color{ 255, 90, 60, 255 } : Color{ 255, 255, 255, 255 };
        DrawCircleV(c, b[i].r, Fade(col, 0.16f * a));
        DrawCircleLines((int)c.x, (int)c.y, b[i].r, Fade(col, 0.85f * a));
        if (i == TB_STICK) DrawCircleV(c, b[i].r * 0.4f, Fade(WHITE, 0.30f * a));
        if (i == tSel) {
            DrawCircleLines((int)c.x, (int)c.y, b[i].r + 4 * u, GOLD);
            DrawCircleLines((int)c.x, (int)c.y, b[i].r + 5 * u, GOLD);
        }
        int fs = std::max(12, (int)(b[i].r * 0.40f));
        int tw = MeasureText(TLABEL[i], fs);
        DrawText(TLABEL[i], (int)(c.x - tw / 2), (int)(c.y - fs / 2), fs, Fade(WHITE, a));
        if (!tLay[i].on) {
            int f2 = std::max(11, (int)(b[i].r * 0.28f));
            DrawText("OFF", (int)(c.x - MeasureText("OFF", f2) / 2), (int)(c.y + fs / 2 + 2), f2, Fade(ORANGE, 0.9f));
        }
    }

    // --- подсказка ---
    const char* hint = "Drag a button to move it. Tap a button to resize or hide it.";
    DrawText(hint, (int)(W / 2 - MeasureText(hint, (int)(20 * u)) / 2), (int)(H - 34 * u), (int)(20 * u), Fade(WHITE, 0.75f));
    if (haveSel) {
        const char* nm = TLABEL[tSel];
        DrawText(TextFormat("Selected: %s   size x%.1f", nm, tLay[tSel].s), (int)(W / 2 - 150 * u), (int)(H - 62 * u), (int)(20 * u), GOLD);
    }

    // --- кнопки панели (рисуются поверх, обрабатывают нажатие) ---
    bool doSave = EdBtn(rSave, "SAVE & BACK", (int)(24 * u), press, p) || back;
    if (EdBtn(rReset, "RESET", (int)(24 * u), press, p)) { TouchDefaults(); tSel = -1; tDrag = -1; }
    DrawRectangleRec(rOpT, Color{ 40, 44, 58, 240 });
    DrawRectangleLinesEx(rOpT, 2, Color{ 200, 200, 210, 210 });
    {
        const char* ot = TextFormat("Opacity %d%%", (int)(tOpacity * 100.0f + 0.5f));
        int fs = (int)(22 * u);
        DrawText(ot, (int)(rOpT.x + (rOpT.width - MeasureText(ot, fs)) / 2), (int)(rOpT.y + (rOpT.height - fs) / 2), fs, WHITE);
    }
    if (EdBtn(rOpM, "-", (int)(30 * u), press, p)) tOpacity = std::max(0.2f, tOpacity - 0.1f);
    if (EdBtn(rOpP, "+", (int)(30 * u), press, p)) tOpacity = std::min(1.0f, tOpacity + 0.1f);
    if (haveSel) {
        if (EdBtn(rMinus, "-", (int)(30 * u), press, p)) tLay[tSel].s = std::max(0.5f, tLay[tSel].s - 0.1f);
        if (EdBtn(rPlus, "+", (int)(30 * u), press, p)) tLay[tSel].s = std::min(2.0f, tLay[tSel].s + 0.1f);
        if (tSel != TB_PAUSE && EdBtn(rOnOff, tLay[tSel].on ? "HIDE" : "SHOW", (int)(22 * u), press, p, !tLay[tSel].on))
            tLay[tSel].on = !tLay[tSel].on;
    }
    if (doSave) { TouchSave(); editingLayout = false; tSel = -1; tDrag = -1; }
}

static Vector2 UIPtr()     { return tPtr; }
static bool    UIDown()    { return tPtrDown; }
static bool    UIPressed() { return tPtrPressed; }
static bool IKeyDown(int k) { return (k == KEY_E && tBtnDown[TB_PLANT]) || (k == KEY_TAB && tBtnDown[TB_SCORE]); }
static bool IKeyPressed(int k) {
    switch (k) {
        case KEY_R: return tBtnPressed[TB_RELOAD];
        case KEY_SPACE: return tBtnPressed[TB_JUMP];
        case KEY_Q: return tBtnPressed[TB_SWAP];
        case KEY_B: return tBtnPressed[TB_BUY];
        case KEY_ESCAPE: return tBtnPressed[TB_PAUSE] || IsKeyPressed(KEY_BACK);
    }
    return false;
}
static bool IMouseDown(int b)    { return b == MOUSE_LEFT_BUTTON ? (tBtnDown[TB_FIRE] || tBtnDown[TB_FIRE2]) : (b == MOUSE_RIGHT_BUTTON ? tScopeOn : false); }
static bool IMousePressed(int b) { return b == MOUSE_LEFT_BUTTON && (tBtnPressed[TB_FIRE] || tBtnPressed[TB_FIRE2]); }
static Vector2 ILook() {
    float k = Lerp(0.4f, 2.5f, gLookSens) / uiScale;
    return Vector2{ tLook.x * k, tLook.y * k };
}
static bool IWalk() { return tMoveMag > 0.0f && tMoveMag < 0.55f; }
static void INoScope(bool hasScope) { if (!hasScope) tScopeOn = false; }
#else
static Vector2 UIPtr()     { return GetMousePosition(); }
static bool    UIDown()    { return IsMouseButtonDown(MOUSE_LEFT_BUTTON); }
static bool    UIPressed() { return IsMouseButtonPressed(MOUSE_LEFT_BUTTON); }
static bool IKeyDown(int k)        { return IsKeyDown(k); }
static bool IKeyPressed(int k)     { return IsKeyPressed(k); }
static bool IMouseDown(int b)      { return IsMouseButtonDown(b); }
static bool IMousePressed(int b)   { return IsMouseButtonPressed(b); }
static Vector2 ILook()             { return GetMouseDelta(); }
static bool IWalk()                { return IsKeyDown(KEY_LEFT_SHIFT); }
static void INoScope(bool)         {}
#endif

static void Feed(const string& s) {
    if (gNetHost) { NetEv e; e.type = EV_FEED; e.s = s; NetEvPush(e); }
    feed.push_back({ s, 6.0f });
    if (feed.size() > 6) feed.erase(feed.begin());
}
static void Banner(const string& t, float sec) {
    banner = t; bannerT = sec;
    if (gNetHost) { NetEv e; e.type = EV_BANNER; e.s = t; e.x = sec; NetEvPush(e); }
}
static Vector3 Eye(const Actor& a) { return Vector3{ a.pos.x, a.pos.y + 1.6f, a.pos.z }; }
static Vector3 Fwd(float yaw, float pitch) { return Vector3{ cosf(pitch) * sinf(yaw), sinf(pitch), cosf(pitch) * cosf(yaw) }; }
static float TurnToward(float cur, float want, float step) {
    float d = want - cur;
    while (d > PI) d -= 2 * PI;
    while (d < -PI) d += 2 * PI;
    if (fabsf(d) <= step) return want;
    return cur + (d > 0 ? step : -step);
}
static int SiteOf(Vector3 p) {
    if (Vector2Distance(Vector2{ p.x, p.z }, SITE_A) < SITE_R) return 0;
    if (Vector2Distance(Vector2{ p.x, p.z }, SITE_B) < SITE_R) return 1;
    return -1;
}

static void SpawnParticles(Vector3 pos, int n, Color c, float speed, float size, float life) {
    for (int i = 0; i < n; i++) {
        if (particles.size() > 500) break;
        Vector3 v = { RandR(-1, 1), RandR(0.2f, 1.4f), RandR(-1, 1) };
        v = Vector3Scale(Vector3Normalize(v), speed * RandR(0.4f, 1.0f));
        float l = life * RandR(0.6f, 1.0f);
        particles.push_back({ pos, v, l, l, size * RandR(0.6f, 1.2f), c });
    }
}

static void AddMoney(Actor& a, int amt) {
    int before = a.money;
    a.money = std::min(16000, a.money + amt);
    int got = a.money - before;
    if (&a == &A[gMe] && got > 0) popups.push_back({ got, 2.2f });
}

// =====================================================================
//  ФИЗИКА / КОЛЛИЗИИ
// =====================================================================
static bool BlockedAt(float x, float z, float y, float r) {
    for (const Wall& w : gWalls) {
        if (y >= w.h - 0.4f) continue;
        float cx = Clamp(x, w.x0, w.x1), cz = Clamp(z, w.z0, w.z1);
        float dx = x - cx, dz = z - cz;
        if (dx * dx + dz * dz < r * r) return true;
    }
    return false;
}
static void MoveActor(Actor& a, float dx, float dz) {
    const float r = 0.4f;
    if (!BlockedAt(a.pos.x + dx, a.pos.z, a.pos.y, r)) a.pos.x += dx;
    if (!BlockedAt(a.pos.x, a.pos.z + dz, a.pos.y, r)) a.pos.z += dz;
}
static float GroundAt(float x, float z, float y) {
    float g = 0.0f;
    for (const Wall& w : gWalls)
        if (x > w.x0 - 0.2f && x < w.x1 + 0.2f && z > w.z0 - 0.2f && z < w.z1 + 0.2f && w.h <= y + 0.45f) g = std::max(g, w.h);
    return g;
}
static void UpdateVertical(Actor& a, float dt) {
    a.vy -= 26.0f * dt;
    a.pos.y += a.vy * dt;
    float g = GroundAt(a.pos.x, a.pos.z, a.pos.y);
    if (a.pos.y <= g) { a.pos.y = g; a.vy = 0.0f; a.onGround = true; }
    else a.onGround = false;
}
static bool CanSee(Vector3 from, Vector3 to) {
    Vector3 d = Vector3Subtract(to, from);
    float L = Vector3Length(d);
    if (L < 0.01f) return true;
    d = Vector3Scale(d, 1.0f / L);
    Ray r = { from, d };
    for (const Wall& w : gWalls) {
        RayCollision c = GetRayCollisionBox(r, w.bb);
        if (c.hit && c.distance > 0.0f && c.distance < L - 0.3f) return false;
    }
    return true;
}

// =====================================================================
//  УРОН, ДЕНЬГИ, СТРЕЛЬБА (карта не разрушается)
// =====================================================================
static const char* TeamTag(int t) { return t == TERRO ? "T" : "CT"; }
static float Dist2(Vector3 a, Vector3 b) { return Vector2Distance(Vector2{ a.x, a.z }, Vector2{ b.x, b.z }); }

static void ReturnFlag(int t) {
    Flag& f = gFlag[t];
    if (f.carrier >= 0 && f.carrier < (int)A.size()) A[f.carrier].carry = -1;
    f.carrier = -1; f.atHome = true; f.returnT = 0.0f; f.pos = f.home;
}
static void ResetFlags() {
    for (int t = 0; t < 2; t++) { gFlag[t].home = FLAG_HOME[t]; ReturnFlag(t); }
    for (Actor& a : A) a.carry = -1;
}
// носитель погиб (или вышел) - флаг падает на месте
static void DropFlag(int idx) {
    Actor& a = A[idx];
    if (a.carry < 0) return;
    Flag& f = gFlag[a.carry];
    f.carrier = -1; f.atHome = false; f.returnT = FLAG_RETURN_T;
    f.pos = Vector3{ a.pos.x, 0.0f, a.pos.z };
    Feed(a.name + " dropped the " + TeamTag(a.carry) + " flag");
    a.carry = -1;
}

static void Hurt(int victim, int attacker, int dmg, bool head, int wid, Vector3 hitPos) {
    Actor& v = A[victim];
    if (!v.alive) return;
    int hpDmg = dmg;
    if (v.armor > 0) {
        int ab = dmg / 2;
        if (ab > v.armor) { hpDmg = dmg - v.armor; v.armor = 0; }
        else { v.armor -= ab; hpDmg = dmg - ab; }
    }
    v.hp -= hpDmg;
    SpawnParticles(hitPos, 5, Col(150, 20, 20), 3.0f, 0.07f, 0.6f);
    if (gNetHost) { NetEv e; e.type = EV_HURT; e.a = (unsigned char)victim; e.b = (unsigned char)(attacker < 0 ? 255 : attacker); e.c = head ? 1 : 0; NetEvPush(e); }
    if (victim == gMe) { hurtT = 0.35f; PlayPool(S.hurt, 0.8f); }
    if (attacker == gMe) {
        hitT = 0.25f;
        if (head) PlayPool(S.headshot, 0.7f); else PlayPool(S.hit, 0.6f);
    }
    if (v.hp <= 0) {
        v.hp = 0;
        v.alive = false;
        v.defusing = false;
        v.deaths++;
        if (gMode != GM_BOMB) {
            v.respawnT = (gMode == GM_TDM) ? 4.0f : 5.0f;
            DropFlag(victim);
        }
        if (victim == gMe) PlayPool(S.death, 0.9f); else PlayAt(S.death, v.pos, 0.9f, 1.0f, 70.0f);
        if (attacker >= 0) {
            A[attacker].kills++;
            if (gMode == GM_TDM && A[attacker].team != v.team) { if (A[attacker].team == TERRO) scoreT++; else scoreCT++; }
            AddMoney(A[attacker], WDEF[wid].reward);
            if (attacker == gMe) PlayPool(S.cash, 0.7f);
            Feed(A[attacker].name + " [" + WDEF[wid].name + "] " + v.name + (head ? " (headshot)" : ""));
        } else {
            Feed(v.name + " died in the explosion");
        }
    }
}

static void FireShot(int shooter, Vector3 origin, Vector3 dir, float dmg, float range, int wid) {
    Ray ray = { origin, dir };
    float best = 1e9f;
    int hitActor = -1;
    bool head = false, wallHit = false;
    Vector3 hp = Vector3Add(origin, Vector3Scale(dir, 200.0f));
    Vector3 hn = { 0, 1, 0 };

    for (const Wall& w : gWalls) {
        RayCollision c = GetRayCollisionBox(ray, w.bb);
        if (c.hit && c.distance > 0.0f && c.distance < best) { best = c.distance; hp = c.point; hn = c.normal; wallHit = true; }
    }
    if (dir.y < -1e-4f) {
        float t = -origin.y / dir.y;
        if (t > 0.0f && t < best) { best = t; hp = Vector3Add(origin, Vector3Scale(dir, t)); hn = Vector3{ 0, 1, 0 }; wallHit = true; }
    }
    for (int i = 0; i < (int)A.size(); i++) {
        if (i == shooter || !A[i].alive || A[i].team == A[shooter].team) continue;
        const Vector3& p = A[i].pos;
        BoundingBox b = { Vector3{ p.x - 0.4f, p.y, p.z - 0.4f }, Vector3{ p.x + 0.4f, p.y + 1.8f, p.z + 0.4f } };
        RayCollision c = GetRayCollisionBox(ray, b);
        if (c.hit && c.distance > 0.0f && c.distance < best) {
            best = c.distance; hitActor = i; hp = c.point;
            head = (c.point.y - p.y) > 1.45f;
            wallHit = false;
        }
    }

    Vector3 muzzle = Vector3Add(origin, Vector3Scale(dir, 0.6f));
    muzzle.y -= 0.12f;
    tracers.push_back({ muzzle, hp, 0.06f });
    if (gNetHost) { NetEv e; e.type = EV_TRACE; e.a = (unsigned char)shooter; e.b = (wallHit && hitActor < 0) ? 1 : 0; e.x = hp.x; e.y = hp.y; e.z = hp.z; NetEvPush(e); }

    if (hitActor >= 0) {
        float dm = dmg;
        if (best > range) dm *= std::max(0.3f, 1.0f - (best - range) / range);
        int d = (int)(dm * (head ? 2.5f : 1.0f));
        if (d < 1) d = 1;
        Hurt(hitActor, shooter, d, head, wid, hp);
    } else if (wallHit) {
        decals.push_back({ Vector3Add(hp, Vector3Scale(hn, 0.02f)), 20.0f });
        if (decals.size() > 150) decals.erase(decals.begin());
        SpawnParticles(Vector3Add(hp, Vector3Scale(hn, 0.05f)), 4, Col(205, 180, 135), 2.2f, 0.06f, 0.7f);
        PlayAt(S.impact, hp, 0.4f, RandR(0.8f, 1.2f), 45.0f);
    }
}

// удар ножом: ближайший враг в конусе перед глазами, не закрытый стеной
static void KnifeSlash(int idx) {
    Actor& p = A[idx];
    Vector3 org = Eye(p);
    Vector3 f = Fwd(p.yaw, p.pitch);
    int best = -1;
    float bestD = 1e9f;
    Vector3 bestPt = org;
    for (int i = 0; i < (int)A.size(); i++) {
        if (i == idx || !A[i].alive || A[i].team == p.team) continue;
        Vector3 c = { A[i].pos.x, A[i].pos.y + 1.1f, A[i].pos.z };
        Vector3 to = Vector3Subtract(c, org);
        float d = Vector3Length(to);
        if (d > KNIFE_REACH || d < 1e-3f) continue;
        if (d > 0.9f && Vector3DotProduct(Vector3Scale(to, 1.0f / d), f) < KNIFE_CONE) continue;
        Ray ray = { org, Vector3Scale(to, 1.0f / d) };
        bool blocked = false;
        for (const Wall& w : gWalls) {
            RayCollision rc = GetRayCollisionBox(ray, w.bb);
            if (rc.hit && rc.distance > 0.0f && rc.distance < d - 0.3f) { blocked = true; break; }
        }
        if (blocked || d >= bestD) continue;
        best = i; bestD = d; bestPt = c;
    }
    if (best >= 0) Hurt(best, idx, WDEF[W_KNIFE].dmg, false, W_KNIFE, bestPt);
}

// =====================================================================
//  БОМБА, ЭКОНОМИКА, РАУНД
// =====================================================================
static void PlantBomb(Vector3 p, int who) {
    bomb.planted = true;
    bomb.pos = p;
    bomb.timer = 40.0f;
    bomb.defuse = 0.0f;
    bomb.beepT = 0.0f;
    gBombNode = NearestNode(Vector2{ p.x, p.z });
    AddMoney(A[who], 300);
    int s = SiteOf(p);
    Banner(string("BOMB HAS BEEN PLANTED - SITE ") + (s == 1 ? "B" : "A"), 3.0f);
    Feed(banner);
    PlayPool(S.planted, 0.9f);
}

static void EndRound(int winner, const string& msg, int winReward) {
    if (state == ROUNDEND) return;
    state = ROUNDEND;
    stTimer = 5.0f;
    if (winner == TERRO) scoreT++; else scoreCT++;
    gLastWinner = winner;
    endMsg = string(winner == TERRO ? "TERRORISTS WIN - " : "COUNTER-TERRORISTS WIN - ") + msg;
    for (int team = 0; team < 2; team++) {
        int reward;
        if (team == winner) {
            reward = winReward;
            lossStreak[team] = std::max(0, lossStreak[team] - 1);
        } else {
            reward = 1400 + 500 * std::min(lossStreak[team], 4);
            if (team == TERRO && bomb.planted) reward += 800;
            lossStreak[team] = std::min(lossStreak[team] + 1, 5);
        }
        for (Actor& a : A) if (a.team == team) AddMoney(a, reward);
    }
    PlayPool(winner == TERRO ? S.win : S.lose, 0.8f);
}

static void ResetAI(Actor& a) {
    a.path.clear(); a.pi = 0; a.goalNode = -1; a.think = 0; a.react = 0; a.strafe = 0; a.holdTimer = 0;
    a.waypoint = -1; a.stuckT = 0; a.stuckAcc = 0; a.strafeDir = 0; a.shots = 0; a.target = -1; a.defusing = false; a.plantProg = 0;
    a.flashT = 0; a.stepT = 0; a.anim = 0;
}

static void BotBuy(Actor& b) {
    if (b.pri < 0) {
        vector<int> aff;
        for (int w = 0; w < NUM_W; w++)
            if (WDEF[w].cat != CAT_PISTOL && w != W_M249 && WDEF[w].price <= b.money) aff.push_back(w);
        if (!aff.empty()) {
            int pick;
            if (Rand01() < 0.6f) {
                pick = aff[0];
                for (int w : aff) if (WDEF[w].price > WDEF[pick].price) pick = w;
            } else pick = aff[rand() % aff.size()];
            b.pri = pick;
            b.money -= WDEF[pick].price;
        } else if (b.sec == W_GLOCK && b.money >= 300 && Rand01() < 0.7f) {
            b.sec = W_P250;
            b.money -= 300;
        }
    }
    if (b.armor < 50 && b.money >= ARMOR_PRICE) { b.armor = 100; b.money -= ARMOR_PRICE; }
}

static bool BuyItem(Actor& p, int item, bool snd = true) {
    if (item == NUM_W) {
        if (p.armor >= 100 || p.money < ARMOR_PRICE) { if (snd) PlayPool(S.denied, 0.7f); return false; }
        p.money -= ARMOR_PRICE;
        p.armor = 100;
        if (snd) PlayPool(S.buy, 0.8f);
        return true;
    }
    const WeaponDef& d = WDEF[item];
    bool owned = (d.cat == CAT_PISTOL) ? (p.sec == item) : (p.pri == item);
    if (owned || p.money < d.price) { if (snd) PlayPool(S.denied, 0.7f); return false; }
    if (d.cat == CAT_PISTOL) p.sec = item; else p.pri = item;
    p.money -= d.price;
    p.mag[item] = d.mag;
    p.res[item] = d.reserve;
    p.cur = item;
    p.reload = 0.0f;
    if (snd) { drawAnim = 1.0f; PlayPool(S.buy, 0.8f); }
    return true;
}

// можно ли сейчас покупать: в бомбе - на разминке, в TDM/CTF - первые секунды после возрождения
static bool CanBuy(const Actor& a) { return a.alive && (state == FREEZE || (gMode != GM_BOMB && a.buyT > 0.0f)); }
static float BuyTimeLeft(const Actor& a) { return (state == FREEZE) ? stTimer : a.buyT; }
static bool AnyHumanAlive(int team) {
    for (const Actor& a : A) if (a.human && a.alive && a.team == team) return true;
    return false;
}

static const Vector3 TSP[4] = { {0,0,54}, {-4,0,54}, {4,0,54}, {0,0,57} };
static const Vector3 CSP[4] = { {-6,0,-54}, {6,0,-54}, {-3,0,-56}, {3,0,-56} };

static void StartRound() {
    roundNo++;
    bomb = Bomb();
    tracers.clear(); decals.clear(); particles.clear();
    int plSite = rand() % 2;
    int planterIdx = -1;                       // кто из ботов-террористов ставит бомбу
    if (gMode == GM_BOMB) for (int i = 1; i < 4; i++) if (!A[i].human) { planterIdx = i; break; }
    for (int i = 0; i < (int)A.size(); i++) {
        Actor& a = A[i];
        if (!a.alive) { a.pri = -1; a.sec = W_GLOCK; a.armor = 0; }   // погиб - потерял снаряжение
        a.alive = true;
        a.hp = 100;
        a.vy = 0; a.onGround = true; a.recoil = 0; a.pitch = 0;
        a.jumpSlow = 0.0f; a.jumpCd = 0.0f; a.respawnT = 0.0f; a.carry = -1; a.plantProg = 0.0f;
        a.buyT = (gMode == GM_BOMB) ? 0.0f : 15.0f;
        a.cd = RandR(0.0f, 0.3f);
        a.reload = 0; a.rph = 0;
        ResetAI(a);
        for (int w = 0; w < NUM_W; w++) { a.mag[w] = WDEF[w].mag; a.res[w] = WDEF[w].reserve; }
        if (i < 4) {
            a.pos = TSP[i]; a.yaw = PI;
            if (!a.human) {
                a.siteSel = (i == planterIdx) ? plSite : rand() % 2;
                a.planter = (i == planterIdx);
                a.startDelay = RandR(0.0f, 3.0f);
            }
        } else {
            a.pos = CSP[i - 4]; a.yaw = 0;
            a.siteSel = (i < 6) ? 0 : 1;
            a.startDelay = RandR(0.0f, 1.0f);
        }
        if (!a.human) BotBuy(a);
        a.cur = (a.pri >= 0) ? a.pri : a.sec;
    }
    if (gMode == GM_CTF) ResetFlags();
    state = FREEZE;
    stTimer = 10.0f;
    roundTime = (gMode == GM_BOMB) ? 115.0f : (gMode == GM_TDM ? TDM_TIME : CTF_TIME);
    hurtT = hitT = 0.0f;
    scoped = false; planting = false;
    drawAnim = 1.0f;
    buyOpen = !gNetClient;
    CaptureMouse(false);
}

static string ActorName(int i) {
    if (i == gMe) return "You";
    if (A[i].human) return "Player " + std::to_string(i + 1);
    return (i < 4) ? "T-Bot " + std::to_string(i) : "CT-Bot " + std::to_string(i - 3);
}

static void NewMatch() {
    A.assign(8, Actor());
    scoreT = scoreCT = 0;
    roundNo = 0;
    lossStreak[0] = lossStreak[1] = 0;
    feed.clear(); popups.clear();
    for (int i = 0; i < 8; i++) {
        A[i].team = (i < 4) ? TERRO : CT;
        A[i].human = gHumanSlot[i] || i == gMe;
        A[i].name = ActorName(i);
        A[i].money = (gMode == GM_BOMB) ? 800 : 3000;
    }
    StartRound();
}

// возрождение в TDM / CTF
static void RespawnActor(int i) {
    Actor& a = A[i];
    a.alive = true; a.hp = 100; a.armor = 0;
    a.pri = -1; a.sec = W_GLOCK; a.cur = W_GLOCK;
    a.vy = 0; a.onGround = true; a.recoil = 0; a.pitch = 0;
    a.jumpSlow = 0.0f; a.jumpCd = 0.0f; a.carry = -1; a.defusing = false; a.plantProg = 0.0f;
    a.cd = 0.3f; a.reload = 0; a.rph = 0; a.flashT = 0.0f; a.respawnT = 0.0f;
    for (int w = 0; w < NUM_W; w++) { a.mag[w] = WDEF[w].mag; a.res[w] = WDEF[w].reserve; }
    ResetAI(a);
    float ox = RandR(-9.0f, 9.0f), oz = RandR(0.0f, 5.0f);
    if (a.team == TERRO) { a.pos = Vector3{ ox, 0, 52.0f + oz }; a.yaw = PI; }
    else                 { a.pos = Vector3{ ox, 0, -52.0f - oz }; a.yaw = 0; }
    AddMoney(a, 2000);
    a.buyT = 12.0f;
    a.startDelay = 0.0f;
    if (!a.human) { BotBuy(a); a.cur = (a.pri >= 0) ? a.pri : a.sec; }
}
static void UpdateRespawns(float dt) {
    for (int i = 0; i < (int)A.size(); i++) {
        Actor& a = A[i];
        if (a.alive) continue;
        a.respawnT -= dt;
        if (a.respawnT <= 0.0f) RespawnActor(i);
    }
}

// ---- CTF: подбор, возврат, захват флага ----
static void UpdateFlags(float dt) {
    if (gMode != GM_CTF || state != LIVE) return;
    for (int t = 0; t < 2; t++) {
        Flag& f = gFlag[t];
        if (f.carrier >= 0) {
            if (!A[f.carrier].alive) DropFlag(f.carrier);
            else f.pos = A[f.carrier].pos;
        } else if (!f.atHome) {
            f.returnT -= dt;
            if (f.returnT <= 0.0f) { ReturnFlag(t); Feed(string(TeamTag(t)) + " flag returned to base"); }
        }
    }
    for (int i = 0; i < (int)A.size(); i++) {
        Actor& a = A[i];
        if (!a.alive) continue;
        for (int t = 0; t < 2; t++) {
            Flag& f = gFlag[t];
            if (f.carrier >= 0 || Dist2(a.pos, f.pos) > FLAG_PICK_R) continue;
            if (a.team != t) {
                if (a.carry < 0) {
                    f.carrier = i; f.atHome = false; a.carry = t;
                    Feed(a.name + " took the " + TeamTag(t) + " flag");
                    Banner(string(TeamTag(a.team)) + " HAS THE " + TeamTag(t) + " FLAG", 2.5f);
                }
            } else if (!f.atHome) {
                ReturnFlag(t);
                AddMoney(a, 300);
                Feed(a.name + " returned the " + TeamTag(t) + " flag");
            }
        }
        if (a.carry >= 0 && gFlag[a.team].atHome && Dist2(a.pos, gFlag[a.team].home) < FLAG_BASE_R) {
            int et = a.carry;
            ReturnFlag(et);
            if (a.team == TERRO) scoreT++; else scoreCT++;
            for (Actor& m : A) if (m.team == a.team) AddMoney(m, (&m == &a) ? 1500 : 500);
            Feed(a.name + " captured the " + TeamTag(et) + " flag!");
            Banner(string(a.team == TERRO ? "TERRORISTS" : "COUNTER-TERRORISTS") + " SCORE!", 3.0f);
            PlayPool(a.team == A[gMe].team ? S.win : S.lose, 0.8f);
        }
    }
}

static void EndMatch(int winner) {
    state = ROUNDEND;
    stTimer = 10.0f;
    if (winner < 0) endMsg = "DRAW - new match starting soon";
    else endMsg = string(winner == TERRO ? "TERRORISTS" : "COUNTER-TERRORISTS") + " WIN THE MATCH";
    gLastWinner = winner;
    if (winner >= 0) PlayPool(winner == A[gMe].team ? S.win : S.lose, 0.8f);
}
static void CheckModeEnd() {
    int lim = (gMode == GM_TDM) ? TDM_LIMIT : CTF_LIMIT;
    if (scoreT >= lim) EndMatch(TERRO);
    else if (scoreCT >= lim) EndMatch(CT);
    else if (roundTime <= 0.0f) EndMatch(scoreT > scoreCT ? TERRO : (scoreCT > scoreT ? CT : -1));
}

static void CheckRoundEnd() {
    if (state != LIVE) return;
    if (gMode != GM_BOMB) { CheckModeEnd(); return; }
    int tA = 0, cA = 0;
    for (const Actor& a : A) if (a.alive) { if (a.team == TERRO) tA++; else cA++; }
    if (bomb.planted) {
        if (bomb.timer <= 0.0f) {
            bomb.exploded = true;
            bomb.explT = 0.0f;
            SpawnParticles(bomb.pos, 120, Col(255, 150, 40), 16.0f, 0.5f, 1.8f);
            SpawnParticles(bomb.pos, 80, Col(70, 60, 55), 9.0f, 0.7f, 2.5f);
            PlayPool(S.explode, 1.0f);
            for (int i = 0; i < (int)A.size(); i++)
                if (A[i].alive && Vector3Distance(A[i].pos, bomb.pos) < 22.0f) Hurt(i, -1, 999, false, 0, A[i].pos);
            EndRound(TERRO, "Bomb exploded", 3500);
        } else if (bomb.defuse >= 10.0f) {
            PlayPool(S.defused, 0.9f);
            EndRound(CT, "Bomb defused", 3500);
        } else if (cA == 0) {
            EndRound(TERRO, "Counter-Terrorists eliminated", 3250);
        }
    } else {
        if (cA == 0) EndRound(TERRO, "Counter-Terrorists eliminated", 3250);
        else if (tA == 0) EndRound(CT, "Terrorists eliminated", 3250);
        else if (roundTime <= 0.0f) EndRound(CT, "Time ran out", 3250);
    }
}

// =====================================================================
//  ИИ БОТОВ
// =====================================================================
static void SetGoal(Actor& b, int g) {
    b.goalNode = g;
    b.path = NodePath(NearestNode(Vector2{ b.pos.x, b.pos.z }), g);
    b.pi = 0;
    b.stuckT = 0.0f;
}
static bool StepToward(Actor& b, Vector2 tp, float speed, float dt) {
    float dx = tp.x - b.pos.x, dz = tp.y - b.pos.z;
    float L = sqrtf(dx * dx + dz * dz);
    if (L < 0.001f) return false;
    dx /= L; dz /= L;
    b.yaw = TurnToward(b.yaw, atan2f(dx, dz), dt * 10.0f);
    Vector3 before = b.pos;
    MoveActor(b, dx * speed * dt, dz * speed * dt);
    float moved = Vector2Distance(Vector2{ before.x, before.z }, Vector2{ b.pos.x, b.pos.z });
    if (moved < speed * dt * 0.3f) { b.stuckT += dt; b.stuckAcc += dt; }
    else { b.stuckT = 0.0f; b.stuckAcc = std::max(0.0f, b.stuckAcc - dt); }
    if (b.stuckT > 0.5f && b.onGround) { b.vy = 9.0f; b.stuckT = 0.0f; }
    if (b.stuckAcc > 1.5f && b.goalNode >= 0) {      // упёрся в угол - строим путь заново от ближайшей свободной точки
        b.path = NodePath(NearestNode(Vector2{ b.pos.x, b.pos.z }), b.goalNode);
        b.pi = 0;
        b.stuckAcc = 0.0f;
    }
    return true;
}

// цели ботов в режиме бомбы: часть охраняет плент, часть бегает по всей карте
static void BotBombGoal(Actor& b, int idx, float dt) {
    bool first = (b.goalNode < 0);
    if (!first && !(b.pi >= b.path.size() && (b.holdTimer -= dt) <= 0.0f)) return;
    int n = (int)gNodes.size();
    int g;
    float roam = (b.team == TERRO) ? 0.65f : ((idx == 4 || idx == 6) ? 0.25f : 0.65f);   // CT 4 и 6 в основном держат плент
    if (b.team == TERRO && bomb.planted) {                                                  // бомба стоит - террористы её охраняют
        int st = std::max(0, SiteOf(bomb.pos));
        g = (st == 0) ? A_GUARD[rand() % 5] : B_GUARD[rand() % 5];
    } else if (b.planter && !bomb.planted) {                                                // закладчик всегда у плента
        g = first ? ((b.siteSel == 0) ? NODE_A : NODE_B) : ((b.siteSel == 0) ? A_GUARD[rand() % 5] : B_GUARD[rand() % 5]);
    } else if (RandR(0.0f, 1.0f) < roam) {                                                  // бегаем по случайным точкам всей карты
        g = rand() % n;
        for (int k = 0; k < 3; k++) {                                                       // чаще уходим со своей половины
            float own = (b.team == TERRO) ? 1.0f : -1.0f;
            if (gNodes[g].y * own > 0.0f && RandR(0.0f, 1.0f) < 0.6f) g = rand() % n; else break;
        }
    } else if (first && b.team == TERRO) {
        g = (b.siteSel == 0) ? NODE_A : NODE_B;
    } else {
        g = (b.siteSel == 0) ? A_GUARD[rand() % 5] : B_GUARD[rand() % 5];
    }
    SetGoal(b, g);
    b.holdTimer = RandR(2.0f, 6.0f);
}

// цели ботов в TDM / CTF
static void BotModeGoal(Actor& b, int idx, float dt) {
    b.holdTimer -= dt;
    bool arrived = (b.goalNode >= 0 && b.pi >= b.path.size());
    int n = (int)gNodes.size();
    if (gMode == GM_TDM) {
        b.hasGoalPos = false;
        if (b.goalNode < 0 || (arrived && b.holdTimer <= 0.0f)) {
            int g = rand() % n;
            for (int k = 0; k < 4; k++) {            // чаще идём на половину врага
                float side = (b.team == TERRO) ? -1.0f : 1.0f;
                if (gNodes[g].y * side > 0.0f) break;
                g = rand() % n;
            }
            SetGoal(b, g);
            b.holdTimer = RandR(2.0f, 6.0f);
        }
        return;
    }
    // CTF: роли по номеру слота
    if (b.goalNode >= 0 && b.holdTimer > 0.0f && !arrived) return;
    b.holdTimer = 0.8f;
    bool attacker = (idx % 4) != 3;      // трое идут за флагом, один защищает базу
    const Flag& own = gFlag[b.team];
    const Flag& foe = gFlag[1 - b.team];
    Vector2 target;
    if (b.carry >= 0)               target = Vector2{ own.home.x, own.home.z };                         // несём флаг домой
    else if (own.carrier >= 0)      target = Vector2{ A[own.carrier].pos.x, A[own.carrier].pos.z };      // наш флаг украли - догнать
    else if (!own.atHome)           target = Vector2{ own.pos.x, own.pos.z };                           // наш флаг лежит - вернуть
    else if (attacker) {                                                                                 // идём за чужим флагом, каждый своей линией
        static const int LANES[3] = { 10, 5, 23 };                                                       // тоннели B, мид, длинная A
        if (b.waypoint == -1) b.waypoint = LANES[rand() % 3];
        if (b.waypoint >= 0 && Vector2Distance(Vector2{ b.pos.x, b.pos.z }, gNodes[b.waypoint]) < 6.0f) b.waypoint = -2;
        target = (b.waypoint >= 0) ? gNodes[b.waypoint] : Vector2{ foe.pos.x, foe.pos.z };
    }
    else {                                                                                               // защита базы
        target = Vector2{ own.home.x + RandR(-8.0f, 8.0f), own.home.z + RandR(-5.0f, 5.0f) * (b.team == TERRO ? -1.0f : 1.0f) };
        b.holdTimer = RandR(3.0f, 6.0f);
    }
    b.goalPos = target; b.hasGoalPos = true;
    int g = NearestNode(target);
    if (g != b.goalNode || arrived) SetGoal(b, g);
}

static void UpdateBot(int idx, float dt) {
    Actor& b = A[idx];
    if (!b.alive) return;
    Vector3 startPos = b.pos;
    UpdateVertical(b, dt);
    b.flashT = std::max(0.0f, b.flashT - dt);
    if (state != LIVE) return;
    if (b.startDelay > 0.0f) { b.startDelay -= dt; return; }

    b.cd -= dt;
    b.think -= dt;

    if (b.think <= 0.0f) {
        b.think = 0.10f;
        int best = -1;
        float bd = 1e9f;
        Vector3 eye = Eye(b);
        for (int i = 0; i < (int)A.size(); i++) {
            const Actor& e = A[i];
            if (!e.alive || e.team == b.team) continue;
            float d = Vector3Distance(b.pos, e.pos);
            if (d > 70.0f || d >= bd) continue;
            float want = atan2f(e.pos.x - b.pos.x, e.pos.z - b.pos.z);
            float diff = want - b.yaw;
            while (diff > PI) diff -= 2 * PI;
            while (diff < -PI) diff += 2 * PI;
            if (fabsf(diff) > 0.95f && d > 12.0f) continue;
            if (!CanSee(eye, Vector3{ e.pos.x, e.pos.y + 1.2f, e.pos.z })) continue;
            best = i; bd = d;
        }
        if (best != b.target) {
            b.target = best;
            if (best >= 0) b.react = RandR(0.15f, 0.32f);
        }
    }

    b.defusing = false;

    if (b.target >= 0 && A[b.target].alive) {
        Actor& t = A[b.target];
        const WeaponDef& wd = WDEF[b.cur];
        float want = atan2f(t.pos.x - b.pos.x, t.pos.z - b.pos.z);
        b.yaw = TurnToward(b.yaw, want, dt * 13.0f);
        b.react -= dt;
        b.strafe -= dt;
        if (b.strafe <= 0.0f) { b.strafe = RandR(0.4f, 1.2f); b.strafeDir = (rand() % 3) - 1; }
        float sx = -cosf(b.yaw), sz = sinf(b.yaw);
        MoveActor(b, sx * b.strafeDir * 3.0f * dt, sz * b.strafeDir * 3.0f * dt);
        if (b.carry >= 0) {          // носитель флага не останавливается: бежит к базе и отстреливается на ходу
            BotModeGoal(b, idx, dt);
            if (b.pi < b.path.size()) {
                Vector2 tp = gNodes[b.path[b.pi]];
                float ddx = tp.x - b.pos.x, ddz = tp.y - b.pos.z, L = sqrtf(ddx * ddx + ddz * ddz);
                if (L < 1.2f) b.pi++;
                else MoveActor(b, ddx / L * 4.6f * dt, ddz / L * 4.6f * dt);
            }
        }

        if (b.react <= 0.0f && b.cd <= 0.0f) {
            Vector3 eye = Eye(b);
            Vector3 aim = { t.pos.x, t.pos.y + ((rand() % 3 == 0) ? 1.65f : 1.1f), t.pos.z };
            Vector3 dir = Vector3Normalize(Vector3Subtract(aim, eye));
            float dist = Vector3Distance(eye, aim);
            float sp = 0.008f + dist * 0.0007f + wd.spread * 0.8f;
            Vector3 right = Vector3Normalize(Vector3CrossProduct(dir, Vector3{ 0, 1, 0 }));
            Vector3 up = Vector3CrossProduct(right, dir);
            float scale = (wd.cat == CAT_SNIPER) ? 0.9f : 0.6f;
            for (int k = 0; k < wd.pellets; k++) {
                Vector3 d2 = Vector3Normalize(Vector3Add(dir, Vector3Add(Vector3Scale(right, RandR(-sp, sp)), Vector3Scale(up, RandR(-sp, sp)))));
                FireShot(idx, eye, d2, wd.dmg * scale, wd.range, b.cur);
            }
            PlayShot(b.cur, b.pos, false);
            NetEvShot(idx, b.cur);
            b.flashT = 0.05f;
            b.cd = wd.autof ? wd.rate * 1.2f : std::max(wd.rate, 0.22f) + RandR(0.0f, 0.15f);
            b.shots++;
            if (wd.autof && b.shots >= 8) { b.shots = 0; b.cd = RandR(0.25f, 0.6f); }
        }
    } else {
        b.target = -1;
        bool handled = false;

        if (gMode == GM_BOMB && b.team == TERRO && b.planter && !bomb.planted && !AnyHumanAlive(TERRO) && SiteOf(b.pos) >= 0 && b.pi >= b.path.size()) {
            b.plantProg += dt;
            if (b.plantProg >= 3.2f) PlantBomb(b.pos, idx);
            handled = true;
        } else b.plantProg = 0.0f;

        bool chaseBomb = (gMode == GM_BOMB && b.team == CT && bomb.planted);
        if (!handled) {
            if (chaseBomb) {
                int g = gBombNode;
                if (b.goalNode != g) SetGoal(b, g);
                if (Vector2Distance(Vector2{ b.pos.x, b.pos.z }, Vector2{ bomb.pos.x, bomb.pos.z }) < 2.2f) {
                    b.defusing = true;
                    handled = true;
                }
            } else if (gMode != GM_BOMB) {
                BotModeGoal(b, idx, dt);
            } else {
                BotBombGoal(b, idx, dt);
            }
        }
        if (!handled) {
            if (b.pi < b.path.size()) {
                Vector2 tp = gNodes[b.path[b.pi]];
                if (Vector2Distance(Vector2{ b.pos.x, b.pos.z }, tp) < 1.2f) b.pi++;
                else StepToward(b, tp, 5.2f, dt);
            } else if (chaseBomb) {
                StepToward(b, Vector2{ bomb.pos.x, bomb.pos.z }, 4.0f, dt);
            } else if (gMode != GM_BOMB && b.hasGoalPos && Vector2Distance(Vector2{ b.pos.x, b.pos.z }, b.goalPos) > 1.0f) {
                StepToward(b, b.goalPos, 5.2f, dt);
            }
        }
    }

    // анимация шагов и звук шагов
    float moved = Vector2Distance(Vector2{ startPos.x, startPos.z }, Vector2{ b.pos.x, b.pos.z });
    b.anim += moved * 2.4f;
    b.stepT += moved;
    if (b.stepT > 2.2f && b.onGround) {
        b.stepT = 0.0f;
        PlayAt(S.step, b.pos, 0.5f, RandR(0.85f, 1.1f), 30.0f);
    }
}

// =====================================================================
//  ИГРОК
// =====================================================================
// ввод одного человека за кадр (локальный игрок или удалённый по сети)
struct PInput {
    float mx = 0.0f, mz = 0.0f;           // движение в осях тела: mx - вправо, mz - вперёд
    float yaw = 0.0f, pitch = 0.0f;       // взгляд (по сети приходит от клиента)
    bool fire = false, firePressed = false, scope = false, walk = false, use = false;
    bool jump = false, reload = false;    // нажатия в этом кадре
    int want = -1;                        // какое оружие взять (индекс) или -1
    int buy = -1;                         // что купить (индекс предмета) или -1
};
static PInput gRemoteIn[8];               // вводы удалённых игроков (заполняет сетевой слой)
static void NetClientInput(const PInput& in);   // клиент: запомнить ввод для отправки хосту (ниже)
static void NetClientBuy(int item);             // клиент: запрос покупки хосту (ниже)

static void SwitchWeapon(Actor& p, int w, bool own) {
    if (p.cur == w || w < 0) return;
    p.cur = w;
    p.reload = 0.0f;
    p.cd = 0.4f;
    if (own) { drawAnim = 1.0f; PlayPool(S.switchW, 0.6f); }
}

// движение, оружие, закладка/разминирование - одинаково для локального и удалённого человека
static void SimHuman(int idx, const PInput& in, float dt, bool predictOnly = false) {
    Actor& p = A[idx];
    bool own = (idx == gMe);
    if (!p.alive) { if (own) { scoped = false; planting = false; } return; }

    p.recoil *= expf(-dt * 5.0f);
    p.flashT = std::max(0.0f, p.flashT - dt);
    p.buyT = std::max(0.0f, p.buyT - dt);

    if (!predictOnly) {
        if (in.want >= 0 && (in.want == p.pri || in.want == p.sec || in.want == W_KNIFE)) SwitchWeapon(p, in.want, own);
        if (in.buy >= 0 && !own && CanBuy(p)) BuyItem(p, in.buy, false);
    }
    int w = p.cur;
    const WeaponDef& wd = WDEF[w];
    bool sc = wd.scope && in.scope && p.reload <= 0.0f;
    if (own) scoped = sc;

    // закладка бомбы / разминирование (держать кнопку USE)
    bool plantingNow = false;
    if (predictOnly) plantingNow = p.plantProg > 0.0f;      // клиент: прогресс закладки приходит от хоста
    else p.defusing = false;
    if (!predictOnly && state == LIVE && gMode == GM_BOMB && p.onGround && in.use) {
        if (p.team == TERRO && !bomb.planted && SiteOf(p.pos) >= 0) {
            plantingNow = true;
            float before = p.plantProg;
            p.plantProg += dt;
            if (own && (int)(before / 0.4f) != (int)(p.plantProg / 0.4f)) PlayPool(S.beep, 0.5f, 0.5f, 1.3f);
            if (p.plantProg >= 3.2f) { PlantBomb(p.pos, idx); plantingNow = false; p.plantProg = 0.0f; }
        } else p.plantProg = 0.0f;
        if (p.team == CT && bomb.planted && Vector2Distance(Vector2{ p.pos.x, p.pos.z }, Vector2{ bomb.pos.x, bomb.pos.z }) < 2.2f) p.defusing = true;
    } else if (!predictOnly) p.plantProg = 0.0f;
    if (own) planting = plantingNow;

    // движение
    float speedXZ = 0.0f;
    bool wasAir = !p.onGround;
    float vyBefore = p.vy;
    p.jumpCd = std::max(0.0f, p.jumpCd - dt);
    if (p.onGround) p.jumpSlow = std::max(0.0f, p.jumpSlow - 0.5f * dt);   // отдышался - скорость возвращается за ~0.7 с
    if (state != FREEZE && !plantingNow && !p.defusing) {
        Vector3 f = { sinf(p.yaw), 0, cosf(p.yaw) };
        Vector3 r = { -cosf(p.yaw), 0, sinf(p.yaw) };
        Vector3 wish = Vector3Add(Vector3Scale(f, in.mz), Vector3Scale(r, in.mx));
        if (Vector3Length(wish) > 0.01f) {
            wish = Vector3Normalize(wish);
            float spd = (in.walk ? 3.2f : 6.2f) * wd.speed;
            if (sc) spd *= 0.5f;
            spd *= (1.0f - p.jumpSlow);
            if (p.carry >= 0) spd *= 0.92f;       // флаг тяжёлый
            speedXZ = spd;
            MoveActor(p, wish.x * spd * dt, wish.z * spd * dt);
            if (p.onGround && !in.walk) {
                p.stepT += dt;
                if (p.stepT > 0.38f) {
                    p.stepT = 0.0f;
                    if (own) PlayPool(S.step, 0.3f, 0.5f, RandR(0.9f, 1.1f));
                    else PlayAt(S.step, p.pos, 0.5f, RandR(0.85f, 1.1f), 30.0f);
                }
            }
        }
        if (in.jump && p.onGround && p.jumpCd <= 0.0f) {
            p.vy = 9.0f;
            p.jumpSlow = std::min(0.6f, p.jumpSlow + 0.15f);   // штраф за сам прыжок
        }
    }
    UpdateVertical(p, dt);
    if (wasAir && p.onGround && vyBefore < -5.0f) {
        if (own) PlayPool(S.step, 0.55f, 0.5f, 0.7f); else PlayAt(S.step, p.pos, 0.5f, 0.7f, 30.0f);
        p.jumpSlow = std::min(0.6f, p.jumpSlow + 0.2f);   // штраф за приземление
        p.jumpCd = 0.4f;                                  // сразу не прыгнуть - банихопа нет
    }
    if (own) {
        bobAmt = Lerp(bobAmt, (speedXZ > 0.1f && p.onGround) ? Clamp(speedXZ / 6.2f, 0.0f, 1.0f) : 0.0f, dt * 8.0f);
        bobT += dt * speedXZ * 1.9f;
    }
    if (predictOnly) return;

    // перезарядка (с анимацией и звуками по фазам)
    if (p.reload > 0.0f) {
        float oldPh = p.rph;
        p.reload -= dt;
        p.rph = Clamp(1.0f - p.reload / wd.reloadT, 0.0f, 1.0f);
        if (own) {
            if (oldPh < 0.2f && p.rph >= 0.2f) PlayPool(S.magOut, 0.6f);
            if (oldPh < 0.58f && p.rph >= 0.58f) PlayPool(S.magIn, 0.7f);
            if (oldPh < 0.82f && p.rph >= 0.82f) PlayPool(S.bolt, 0.6f);
        }
        if (p.reload <= 0.0f) {
            int need = wd.mag - p.mag[w];
            int take = std::min(need, p.res[w]);
            p.mag[w] += take;
            p.res[w] -= take;
            p.reload = 0.0f;
            p.rph = 0.0f;
        }
    } else if (state != FREEZE && (in.reload || p.mag[w] == 0) && p.mag[w] < wd.mag && p.res[w] > 0) {
        p.reload = wd.reloadT;
        p.rph = 0.0f;
    }

    // стрельба
    p.cd -= dt;
    if (own) muzzleT -= dt;
    bool want = wd.autof ? in.fire : in.firePressed;
    if (state == LIVE && want && p.cd <= 0.0f && p.reload <= 0.0f && !plantingNow && !p.defusing) {
        if (w == W_KNIFE) {                       // нож: без патронов, без вспышки и отдачи
            p.cd = wd.rate;
            KnifeSlash(idx);
            PlayShot(w, p.pos, own);
            NetEvShot(idx, w);
            if (own) knifeT = 1.0f;
        } else if (p.mag[w] > 0) {
            p.mag[w]--;
            p.cd = wd.rate;
            float sp = wd.spread + speedXZ * 0.0008f + (p.onGround ? 0.0f : 0.03f);
            if (wd.scope && !sc) sp += 0.06f;
            Vector3 f = Fwd(p.yaw, p.pitch + p.recoil);
            Vector3 right = Vector3Normalize(Vector3CrossProduct(f, Vector3{ 0, 1, 0 }));
            Vector3 up = Vector3CrossProduct(right, f);
            for (int k = 0; k < wd.pellets; k++) {
                Vector3 dir = Vector3Normalize(Vector3Add(f, Vector3Add(Vector3Scale(right, RandR(-sp, sp)), Vector3Scale(up, RandR(-sp, sp)))));
                FireShot(idx, Eye(p), dir, (float)wd.dmg, wd.range, w);
            }
            PlayShot(w, p.pos, own);
            NetEvShot(idx, w);
            p.flashT = 0.05f;
            p.recoil += wd.recoil;
            p.yaw += RandR(-0.004f, 0.004f);
            if (own) { muzzleT = 0.05f; gunKick = 1.0f; }
        } else {
            p.cd = 0.3f;
            if (own) PlayPool(S.empty, 0.6f);
        }
    }
}

// ввод локального игрока (клавиатура / сенсорные кнопки)
static PInput ReadLocalInput(const Actor& p, float wheel) {
    PInput in;
    in.yaw = p.yaw; in.pitch = p.pitch;
#ifdef SS_TOUCH
    in.mx = tMove.x; in.mz = tMove.y;
#else
    in.mz = (IKeyDown(KEY_W) ? 1.0f : 0.0f) - (IKeyDown(KEY_S) ? 1.0f : 0.0f);
    in.mx = (IKeyDown(KEY_D) ? 1.0f : 0.0f) - (IKeyDown(KEY_A) ? 1.0f : 0.0f);
#endif
    in.walk = IWalk();
    in.fire = IMouseDown(MOUSE_LEFT_BUTTON);
    in.firePressed = IMousePressed(MOUSE_LEFT_BUTTON);
    in.scope = IMouseDown(MOUSE_RIGHT_BUTTON);
    in.use = IKeyDown(KEY_E);
    in.jump = IKeyPressed(KEY_SPACE);
    in.reload = IKeyPressed(KEY_R);
    if (IKeyPressed(KEY_ONE) && p.pri >= 0) in.want = p.pri;
    if (IKeyPressed(KEY_TWO)) in.want = p.sec;
    if (IKeyPressed(KEY_THREE)) in.want = W_KNIFE;
    if (IKeyPressed(KEY_Q) || wheel != 0.0f) {      // по кругу: основное -> пистолет -> нож
        int slots[3], n = 0;
        if (p.pri >= 0) slots[n++] = p.pri;
        slots[n++] = p.sec;
        slots[n++] = W_KNIFE;
        int at = 0;
        for (int i = 0; i < n; i++) if (slots[i] == p.cur) at = i;
        in.want = slots[(at + 1) % n];
    }
    return in;
}

static void UpdatePlayer(float dt) {
    Actor& p = A[gMe];
    if (!p.alive) {
        scoped = false; planting = false;
        if (gNetClient) { PInput z; z.yaw = p.yaw; z.pitch = p.pitch; NetClientInput(z); }
        return;
    }
    bool active = !buyOpen && !paused;

    if (active) {
        if (skipMouse > 0) skipMouse--;
        else {
            Vector2 md = ILook();
            float sens = scoped ? 0.0008f : 0.0022f;
            md.x *= uiScale; md.y *= uiScale;   // вернуть реальные пиксели мыши
            p.yaw -= md.x * sens;
            p.pitch = Clamp(p.pitch - md.y * sens, -1.5f, 1.5f);
        }
    }
    gunKick = std::max(0.0f, gunKick - dt * 12.0f);
    knifeT = std::max(0.0f, knifeT - dt * 4.0f);
    drawAnim = std::max(0.0f, drawAnim - dt * 3.0f);

    float wheel = GetMouseWheelMove();
    INoScope(WDEF[p.cur].scope);
    PInput in = ReadLocalInput(p, wheel);
    if (!active) {      // меню закупки / пауза: только смена оружия, без движения и стрельбы
        in.mx = in.mz = 0.0f; in.fire = in.firePressed = in.scope = in.use = in.jump = in.reload = false;
        if (paused) in.want = -1;
    }
    if (gNetClient) { NetClientInput(in); SimHuman(gMe, in, dt, true); }   // клиент: ввод уходит хосту, у себя только предсказываем движение
    else SimHuman(gMe, in, dt);
}

// люди, подключённые по сети (работает только у хоста)
static void UpdateRemoteHumans(float dt) {
    if (!gNetHost) return;
    for (int i = 0; i < (int)A.size(); i++) {
        if (i == gMe || !A[i].human) continue;
        PInput& in = gRemoteIn[i];
        A[i].yaw = in.yaw;
        A[i].pitch = in.pitch;
        Vector3 before = A[i].pos;
        SimHuman(i, in, dt);
        float mv = Vector2Distance(Vector2{ before.x, before.z }, Vector2{ A[i].pos.x, A[i].pos.z });
        A[i].anim += mv * 2.4f;
        in.jump = in.reload = in.firePressed = false;    // разовые нажатия израсходованы
        in.want = -1; in.buy = -1;
    }
}

// =====================================================================
//  ОБНОВЛЕНИЕ ИГРЫ
// =====================================================================
static void TickEffects(float dt);
static void UpdateGame(float dt) {
    TickEffects(dt);

    int prevSec = (int)ceilf(stTimer);
    stTimer -= dt;
    if (state == FREEZE) {
        int sec = (int)ceilf(stTimer);
        if (sec != prevSec && sec <= 3 && sec > 0) PlayPool(S.uiTick, 0.6f);
        if (stTimer <= 0.0f) {
            state = LIVE;
            PlayPool(S.roundStart, 0.8f);
            if (buyOpen) { buyOpen = false; CaptureMouse(true); }
        }
    }
    if (state == ROUNDEND && stTimer <= 0.0f) { if (gMode == GM_BOMB) StartRound(); else NewMatch(); }

    if (state == LIVE) {
        if (bomb.planted) bomb.timer -= dt; else roundTime -= dt;
    }

    UpdatePlayer(dt);
    UpdateRemoteHumans(dt);
    for (int i = 0; i < (int)A.size(); i++) if (!A[i].human) UpdateBot(i, dt);
    if (gMode != GM_BOMB && state == LIVE) { UpdateRespawns(dt); UpdateFlags(dt); }

    if (state == LIVE && bomb.planted) {
        bool any = false;
        for (const Actor& a : A) if (a.alive && a.defusing) any = true;
        if (any) bomb.defuse += dt; else bomb.defuse = 0.0f;
        // писк бомбы
        bomb.beepT -= dt;
        if (bomb.beepT <= 0.0f && bomb.timer > 0.0f) {
            float k = Clamp(bomb.timer / 40.0f, 0.0f, 1.0f);
            bomb.beepT = 0.12f + 0.9f * k * k;
            bomb.blinkT = 0.12f;
            PlayAt(S.beep, bomb.pos, 0.9f, 1.0f, 200.0f);
        }
    }
    bomb.blinkT = std::max(0.0f, bomb.blinkT - dt);
    if (bomb.exploded) bomb.explT += dt;

    CheckRoundEnd();

}

static void TickEffects(float dt) {
    hurtT = std::max(0.0f, hurtT - dt);
    hitT = std::max(0.0f, hitT - dt);
    bannerT = std::max(0.0f, bannerT - dt);
    for (auto& t : tracers) t.t -= dt;
    tracers.erase(std::remove_if(tracers.begin(), tracers.end(), [](const Tracer& t) { return t.t <= 0.0f; }), tracers.end());
    for (auto& d : decals) d.t -= dt;
    decals.erase(std::remove_if(decals.begin(), decals.end(), [](const Decal& d) { return d.t <= 0.0f; }), decals.end());
    for (auto& f : feed) f.t -= dt;
    feed.erase(std::remove_if(feed.begin(), feed.end(), [](const FeedItem& f) { return f.t <= 0.0f; }), feed.end());
    for (auto& po : popups) po.t -= dt;
    popups.erase(std::remove_if(popups.begin(), popups.end(), [](const Popup& po) { return po.t <= 0.0f; }), popups.end());
    for (auto& pa : particles) {
        pa.t -= dt;
        pa.v.y -= 9.0f * dt;
        pa.p = Vector3Add(pa.p, Vector3Scale(pa.v, dt));
        if (pa.p.y < 0.03f) { pa.p.y = 0.03f; pa.v = Vector3Scale(pa.v, 0.2f); }
    }
    particles.erase(std::remove_if(particles.begin(), particles.end(), [](const Particle& pa) { return pa.t <= 0.0f; }), particles.end());
}

// =====================================================================
//  СЕТЬ: игра по локальной сети (Wi-Fi), протокол UDP.
//  Хост считает всю игру (боты, урон, раунды), клиенты шлют ввод и получают снимки мира ~30 раз/с.
//  Хост находится автоматически: он рассылает объявление по сети, клиент выбирает игру из списка.
// =====================================================================
static int gNetPort = 27631;               // порт UDP (меняется только в тестах)
static const int NET_VER = 1;
enum { PK_ANNOUNCE = 1, PK_JOIN, PK_WELCOME, PK_INPUT, PK_SNAP, PK_LEAVE, PK_REJECT, PK_LOBBY };
#if defined(_WIN32)
static const bool NET_SUPPORTED = false;     // в Windows-сборке сеть не включена
#else
static const bool NET_SUPPORTED = true;
#endif

struct NetAddr { unsigned ip = 0; unsigned short port = 0; };
static bool operator==(const NetAddr& a, const NetAddr& b) { return a.ip == b.ip && a.port == b.port; }

struct NW {   // запись пакета
    unsigned char b[1400]; int n = 0; bool ok = true;
    void u8(int v) { if (n < 1400) b[n++] = (unsigned char)v; else ok = false; }
    void u16(int v) { u8(v & 255); u8((v >> 8) & 255); }
    void f32(float v) { unsigned char t[4]; memcpy(t, &v, 4); for (int i = 0; i < 4; i++) u8(t[i]); }
    void str(const string& s) { int l = (int)std::min<size_t>(s.size(), 80); u8(l); for (int i = 0; i < l; i++) u8((unsigned char)s[i]); }
    void header(int type) { u8('S'); u8('S'); u8(NET_VER); u8(type); }
};
struct NR {   // чтение пакета
    const unsigned char* b; int n; int p = 0; bool ok = true;
    NR(const unsigned char* d, int len) : b(d), n(len) {}
    int u8() { if (p < n) return b[p++]; ok = false; return 0; }
    int u16() { int a = u8(); int c = u8(); return a | (c << 8); }
    float f32() { unsigned char t[4]; for (int i = 0; i < 4; i++) t[i] = (unsigned char)u8(); float v; memcpy(&v, t, 4); return v; }
    string str() { int l = u8(); string s; for (int i = 0; i < l && ok; i++) s.push_back((char)u8()); return s; }
};

static int gSock = -1;
static double gNetClock = 0.0;
static string gNetMsg;                       // сообщение для меню (статус / ошибка)

static bool NetOpen() {
    if (gSock >= 0) return true;
#if !defined(_WIN32)
    int sk = socket(AF_INET, SOCK_DGRAM, 0);
    if (sk < 0) return false;
    int one = 1;
    setsockopt(sk, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
    setsockopt(sk, SOL_SOCKET, SO_BROADCAST, &one, sizeof(one));
    int fl = fcntl(sk, F_GETFL, 0);
    fcntl(sk, F_SETFL, fl | O_NONBLOCK);
    sockaddr_in a; memset(&a, 0, sizeof(a));
    a.sin_family = AF_INET; a.sin_addr.s_addr = htonl(INADDR_ANY); a.sin_port = htons((unsigned short)gNetPort);
    if (bind(sk, (sockaddr*)&a, sizeof(a)) < 0) { close(sk); return false; }
    gSock = sk;
    return true;
#else
    return false;
#endif
}
static void NetClose() {
#if !defined(_WIN32)
    if (gSock >= 0) close(gSock);
#endif
    gSock = -1;
}
static bool NetSend(const NetAddr& to, const unsigned char* d, int n) {
#if !defined(_WIN32)
    if (gSock < 0) return false;
    sockaddr_in a; memset(&a, 0, sizeof(a));
    a.sin_family = AF_INET; a.sin_addr.s_addr = to.ip; a.sin_port = to.port;
    return sendto(gSock, d, (size_t)n, 0, (sockaddr*)&a, sizeof(a)) == n;
#else
    (void)to; (void)d; (void)n; return false;
#endif
}
static void NetBroadcast(const unsigned char* d, int n) {
#if !defined(_WIN32)
    NetAddr a; a.ip = htonl(INADDR_BROADCAST); a.port = htons((unsigned short)gNetPort);
    NetSend(a, d, n);
#else
    (void)d; (void)n;
#endif
}
static int NetRecv(unsigned char* buf, int cap, NetAddr& from) {
#if !defined(_WIN32)
    if (gSock < 0) return -1;
    sockaddr_in a; socklen_t l = sizeof(a);
    int n = (int)recvfrom(gSock, buf, (size_t)cap, 0, (sockaddr*)&a, &l);
    if (n <= 0) return -1;
    from.ip = a.sin_addr.s_addr; from.port = a.sin_port;
    return n;
#else
    (void)buf; (void)cap; (void)from; return -1;
#endif
}

// ---------------- хост ----------------
struct Peer { bool used = false, synced = false; NetAddr addr; double last = 0; unsigned char jN = 0, rN = 0, fN = 0, wN = 0, bN = 0; };
static Peer gPeers[8];                       // индекс = слот игрока
static bool gHostInMatch = false;
static float gAnnT = 0.0f, gSnapT = 0.0f, gLobT = 0.0f;
static unsigned short gSnapSeq = 0;

static int NetFreeSlot() {
    static const int order[7] = { 4, 1, 5, 2, 6, 3, 7 };   // новички чередуют команды, начиная с CT
    for (int o : order) if (!gHumanSlot[o]) return o;
    return -1;
}
static int NetPeerCount() { int c = 0; for (const Peer& p : gPeers) if (p.used) c++; return c; }
static int NetHumanMask() { int m = 0; for (int i = 0; i < 8; i++) if (gHumanSlot[i]) m |= (1 << i); return m; }

// ---------------- клиент ----------------
struct FoundHost { NetAddr addr; int mode = 0, humans = 1; bool inMatch = false; double last = 0; };
static vector<FoundHost> gFound;
static int gCliState = 0;                    // 0 - поиск, 1 - подключаемся, 2 - в лобби, 3 - в игре
static NetAddr gHostAddr;
static double gCliLastRx = 0.0, gCliJoinStart = 0.0;
static float gCliJoinT = 0.0f, gCliInT = 0.0f;
static int gLobMode = 0, gLobMask = 1;
static PInput gCliIn;
static unsigned char cJ = 0, cR = 0, cF = 0, cW = 0, cB = 0;
static int cWV = 255, cBV = 255;
struct NetTarget { Vector3 pos = { 0, 0, 0 }; float yaw = 0.0f; bool valid = false; };
static NetTarget gTgt[8];
static unsigned short gLastSeq = 0;
static bool gHaveSeq = false;

static void NetClientInput(const PInput& in) {
    gCliIn.mx = in.mx; gCliIn.mz = in.mz; gCliIn.yaw = in.yaw; gCliIn.pitch = in.pitch;
    gCliIn.fire = in.fire; gCliIn.scope = in.scope; gCliIn.walk = in.walk; gCliIn.use = in.use;
    if (in.jump) cJ++;
    if (in.reload) cR++;
    if (in.firePressed) cF++;
    if (in.want >= 0) { cW++; cWV = in.want; }
}
static void NetClientBuy(int item) { cB++; cBV = item; }

// ---------------- остановка / выход ----------------
static void NetStop() {
    if (gSock >= 0) {
        NW w; w.header(PK_LEAVE);
        if (gNetHost) { for (const Peer& p : gPeers) if (p.used) NetSend(p.addr, w.b, w.n); }
        else if (gNetClient && gCliState >= 1) NetSend(gHostAddr, w.b, w.n);
    }
    NetClose();
    gNetHost = gNetClient = false;
    gHostInMatch = false;
    gCliState = 0;
    for (Peer& p : gPeers) p = Peer();
    gEvq.clear(); gFound.clear();
    for (int i = 0; i < 8; i++) gHumanSlot[i] = (i == 0);
    gMe = 0;
}
static bool NetHostStart() {
    if (!NET_SUPPORTED || !NetOpen()) { gNetMsg = "Network is not available (is Wi-Fi on?)"; return false; }
    for (Peer& p : gPeers) p = Peer();
    gMe = 0;
    for (int i = 0; i < 8; i++) gHumanSlot[i] = (i == 0);
    gNetHost = true; gNetClient = false; gHostInMatch = false;
    gEvq.clear(); gNetMsg.clear();
    gAnnT = 0.0f; gLobT = 0.0f;
    return true;
}
static bool NetClientStartBrowse() {
    if (!NET_SUPPORTED || !NetOpen()) { gNetMsg = "Network is not available (is Wi-Fi on?)"; return false; }
    gNetHost = false; gNetClient = true; gCliState = 0;
    gFound.clear(); gNetMsg.clear();
    gMe = 0;
    for (int i = 0; i < 8; i++) gHumanSlot[i] = (i == 0);
    return true;
}
static void NetClientJoin(const NetAddr& host) {
    gHostAddr = host; gCliState = 1;
    gCliJoinStart = gNetClock; gCliLastRx = gNetClock; gCliJoinT = 0.0f;
    cJ = cR = cF = cW = cB = 0; cWV = cBV = 255;
    gHaveSeq = false; gNetMsg.clear();
}
// клиент вышел / потерял связь: вернуться в меню поиска
static void NetClientLeave(const string& msg) {
    bool wasGame = (app == APP_GAME);
    NetStop();
    gNetMsg = msg;
    if (wasGame) {
        app = APP_MENU; paused = false; buyOpen = false;
        CaptureMouse(false);
        if (S.musicOK) { SetSoundVolume(S.music, 0.5f); PlaySound(S.music); }
        playOpen = true; lanScreen = 2;
    }
    if (lanScreen == 2) { string keep = msg; NetClientStartBrowse(); gNetMsg = keep; }
}

static void NetDropPeer(int slot) {
    gPeers[slot] = Peer();
    gHumanSlot[slot] = false;
    if (gHostInMatch && slot < (int)A.size()) {
        Feed(A[slot].name + " left the game");
        DropFlag(slot);
        A[slot].human = false; A[slot].name = ActorName(slot);
        ResetAI(A[slot]);
    }
}

static void NetHostStartMatch() {
    gHostInMatch = true; gEvq.clear(); gMe = 0;
    for (int i = 0; i < 8; i++) gHumanSlot[i] = (i == 0) || gPeers[i].used;
    app = APP_GAME; playOpen = false; lanScreen = 0; paused = false;
    if (S.musicOK) StopSound(S.music);
    NewMatch();
}

static void NetHostPacket(const unsigned char* d, int n, const NetAddr& from) {
    NR r(d, n);
    if (r.u8() != 'S' || r.u8() != 'S' || r.u8() != NET_VER) return;
    int type = r.u8();
    int slot = -1;
    for (int i = 0; i < 8; i++) if (gPeers[i].used && gPeers[i].addr == from) slot = i;
    if (type == PK_JOIN) {
        if (slot < 0) {
            int fs = NetFreeSlot();
            if (fs < 0) { NW w; w.header(PK_REJECT); NetSend(from, w.b, w.n); return; }
            slot = fs;
            gPeers[slot] = Peer();
            gPeers[slot].used = true; gPeers[slot].addr = from;
            gHumanSlot[slot] = true;
            if (gHostInMatch) {
                A[slot].human = true; A[slot].name = ActorName(slot);
                ResetAI(A[slot]);
                Feed(A[slot].name + " joined the game");
            }
        }
        gPeers[slot].last = gNetClock;
        NW w; w.header(PK_WELCOME); w.u8(slot); w.u8(gMode); w.u8(gHostInMatch ? 1 : 0); w.u8(NetHumanMask());
        NetSend(from, w.b, w.n);
    } else if (slot >= 0) {
        Peer& pr = gPeers[slot];
        pr.last = gNetClock;
        if (type == PK_INPUT) {
            int mx = (signed char)r.u8(), mz = (signed char)r.u8();
            float yaw = r.f32(), pitch = r.f32();
            int fl = r.u8(), jN = r.u8(), rN = r.u8(), fN = r.u8(), wN = r.u8(), wv = r.u8(), bN = r.u8(), bv = r.u8();
            if (!r.ok || !std::isfinite(yaw) || !std::isfinite(pitch)) return;
            PInput& in = gRemoteIn[slot];
            in.mx = Clamp(mx / 127.0f, -1.0f, 1.0f); in.mz = Clamp(mz / 127.0f, -1.0f, 1.0f);
            in.yaw = yaw; in.pitch = Clamp(pitch, -1.5f, 1.5f);
            in.fire = (fl & 1) != 0; in.scope = (fl & 2) != 0; in.walk = (fl & 4) != 0; in.use = (fl & 8) != 0;
            if (!pr.synced) { pr.synced = true; pr.jN = (unsigned char)jN; pr.rN = (unsigned char)rN; pr.fN = (unsigned char)fN; pr.wN = (unsigned char)wN; pr.bN = (unsigned char)bN; }
            if (jN != pr.jN) { in.jump = true; pr.jN = (unsigned char)jN; }
            if (rN != pr.rN) { in.reload = true; pr.rN = (unsigned char)rN; }
            if (fN != pr.fN) { in.firePressed = true; pr.fN = (unsigned char)fN; }
            if (wN != pr.wN) { if (wv < NUM_W) in.want = wv; pr.wN = (unsigned char)wN; }
            if (bN != pr.bN) { if (bv <= NUM_W) in.buy = bv; pr.bN = (unsigned char)bN; }
        } else if (type == PK_LEAVE) {
            NetDropPeer(slot);
        }
    }
}

static void NetPutEvents(NW& w) {
    int cnt = 0;
    int cntPos = w.n; w.u8(0);
    for (const NetEv& e : gEvq) {
        if (w.n > 1020 || cnt >= 30) break;
        w.u8(e.type);
        switch (e.type) {
            case EV_SHOT:   w.u8(e.a); w.u8(e.b); break;
            case EV_TRACE:  w.u8(e.a); w.u8(e.b); w.f32(e.x); w.f32(e.y); w.f32(e.z); break;
            case EV_HURT:   w.u8(e.a); w.u8(e.b); w.u8(e.c); break;
            case EV_FEED:   w.str(e.s); break;
            case EV_BANNER: w.f32(e.x); w.str(e.s); break;
            default: break;
        }
        cnt++;
    }
    w.b[cntPos] = (unsigned char)cnt;
}

static void NetHostSendSnapshots() {
    NW base;
    base.header(PK_SNAP);
    base.u16(gSnapSeq++);
    base.u8(state); base.f32(stTimer); base.f32(roundTime);
    base.u16(scoreT); base.u16(scoreCT);
    base.u8(gLastWinner + 1);
    base.u8((bomb.planted ? 1 : 0) | (bomb.exploded ? 2 : 0));
    if (bomb.planted || bomb.exploded) { base.f32(bomb.pos.x); base.f32(bomb.pos.y); base.f32(bomb.pos.z); base.f32(bomb.timer); base.f32(bomb.defuse); }
    if (state == ROUNDEND) base.str(endMsg);
    if (gMode == GM_CTF) for (int t = 0; t < 2; t++) { base.u8(gFlag[t].carrier + 1); base.u8(gFlag[t].atHome ? 1 : 0); base.f32(gFlag[t].pos.x); base.f32(gFlag[t].pos.z); }
    for (int i = 0; i < 8; i++) {
        const Actor& a = A[i];
        base.u8((a.alive ? 1 : 0) | (a.human ? 2 : 0) | (a.defusing ? 4 : 0) | (a.flashT > 0.0f ? 8 : 0));
        base.u8(a.hp); base.u8(a.armor); base.u8(a.cur); base.u8(a.pri + 1); base.u8(a.sec); base.u8(a.carry + 1);
        base.f32(a.pos.x); base.f32(a.pos.y); base.f32(a.pos.z); base.f32(a.yaw); base.f32(a.pitch);
        base.u16(a.kills); base.u16(a.deaths);
    }
    NetPutEvents(base);
    for (int i = 0; i < 8; i++) {
        if (!gPeers[i].used) continue;
        NW w = base;
        const Actor& a = A[i];
        w.u16(a.money); w.u16(a.mag[a.cur]); w.u16(a.res[a.cur]);
        w.f32(a.reload); w.f32(a.rph); w.f32(a.recoil); w.f32(a.buyT); w.f32(a.respawnT); w.f32(a.plantProg); w.f32(a.jumpSlow); w.f32(a.jumpCd);
        if (w.ok) NetSend(gPeers[i].addr, w.b, w.n);
    }
    gEvq.clear();
}

static void NetHostTick(float dt) {
    unsigned char buf[1500]; NetAddr from;
    for (int k = 0; k < 128; k++) { int n = NetRecv(buf, sizeof(buf), from); if (n < 0) break; NetHostPacket(buf, n, from); }
    for (int i = 0; i < 8; i++) if (gPeers[i].used && gNetClock - gPeers[i].last > 6.0) NetDropPeer(i);
    gAnnT -= dt;
    if (gAnnT <= 0.0f) {
        gAnnT = 1.0f;
        NW w; w.header(PK_ANNOUNCE); w.u8(gMode); w.u8(1 + NetPeerCount()); w.u8(gHostInMatch ? 1 : 0);
        NetBroadcast(w.b, w.n);
    }
    if (!gHostInMatch) {
        gLobT -= dt;
        if (gLobT <= 0.0f) {
            gLobT = 0.4f;
            NW w; w.header(PK_LOBBY); w.u8(gMode); w.u8(NetHumanMask()); w.u8(0);
            for (const Peer& p : gPeers) if (p.used) NetSend(p.addr, w.b, w.n);
        }
    } else {
        gSnapT -= dt;
        if (gSnapT <= 0.0f) { gSnapT = 1.0f / 30.0f; NetHostSendSnapshots(); }
    }
}

// ---- клиент: вход в игру и применение снимка ----
static void NetClientEnterGame() {
    gMode = gLobMode;
    A.assign(8, Actor());
    for (int i = 0; i < 8; i++) { A[i].team = (i < 4) ? TERRO : CT; A[i].human = ((gLobMask >> i) & 1) != 0 || i == gMe; A[i].name = ActorName(i); }
    feed.clear(); popups.clear(); tracers.clear(); decals.clear(); particles.clear();
    scoreT = scoreCT = 0; bomb = Bomb(); state = ROUNDEND; stTimer = 0.0f;
    ResetFlags();
    for (int i = 0; i < 8; i++) gTgt[i].valid = false;
    app = APP_GAME; paused = false; playOpen = false; lanScreen = 0; buyOpen = false;
    if (S.musicOK) StopSound(S.music);
    gCliState = 3;
}

static void NetClientApply(NR& r) {
    int seq = r.u16();
    int st = r.u8();
    float stT = r.f32(), rT = r.f32();
    int sT = (int16_t)r.u16(), sC = (int16_t)r.u16();
    int win = r.u8() - 1;
    int bf = r.u8();
    bool planted = (bf & 1) != 0, exploded = (bf & 2) != 0;
    Vector3 bp = { 0, 0, 0 }; float bt = 0, bd = 0;
    if (planted || exploded) { bp.x = r.f32(); bp.y = r.f32(); bp.z = r.f32(); bt = r.f32(); bd = r.f32(); }
    string em; if (st == ROUNDEND) em = r.str();
    struct FS { int car = -1; bool home = true; float x = 0, z = 0; } fs[2];
    if (gMode == GM_CTF) for (int t = 0; t < 2; t++) { fs[t].car = r.u8() - 1; fs[t].home = r.u8() != 0; fs[t].x = r.f32(); fs[t].z = r.f32(); }
    struct AS { int fl, hp, ar, cur, pri, sec, carry, kills, deaths; float x, y, z, yaw, pitch; } as[8];
    for (int i = 0; i < 8; i++) {
        AS& q = as[i];
        q.fl = r.u8(); q.hp = r.u8(); q.ar = r.u8(); q.cur = r.u8(); q.pri = r.u8() - 1; q.sec = r.u8(); q.carry = r.u8() - 1;
        q.x = r.f32(); q.y = r.f32(); q.z = r.f32(); q.yaw = r.f32(); q.pitch = r.f32(); q.kills = r.u16(); q.deaths = r.u16();
    }
    vector<NetEv> evs;
    int ec = r.u8();
    for (int k = 0; k < ec && r.ok; k++) {
        NetEv e; e.type = (unsigned char)r.u8();
        switch (e.type) {
            case EV_SHOT:   e.a = (unsigned char)r.u8(); e.b = (unsigned char)r.u8(); break;
            case EV_TRACE:  e.a = (unsigned char)r.u8(); e.b = (unsigned char)r.u8(); e.x = r.f32(); e.y = r.f32(); e.z = r.f32(); break;
            case EV_HURT:   e.a = (unsigned char)r.u8(); e.b = (unsigned char)r.u8(); e.c = (unsigned char)r.u8(); break;
            case EV_FEED:   e.s = r.str(); break;
            case EV_BANNER: e.x = r.f32(); e.s = r.str(); break;
            default: r.ok = false; break;
        }
        evs.push_back(e);
    }
    int money = r.u16(), mg = r.u16(), rs = r.u16();
    float rel = r.f32(), rph = r.f32(), rec = r.f32(), buyT = r.f32(), respT = r.f32(), plantP = r.f32(), jSlow = r.f32(), jCd = r.f32();
    if (!r.ok) return;                                        // обрезанный / битый пакет - пропускаем
    if (gHaveSeq && (unsigned short)(seq - gLastSeq) > 32768) return;   // устаревший (пришёл позже нового)
    gLastSeq = (unsigned short)seq; gHaveSeq = true;
    if (st < 0 || st > 2) return;

    // состояние раунда
    GState ns = (GState)st;
    if (ns != state) {
        if (ns == FREEZE) { buyOpen = true; CaptureMouse(false); tracers.clear(); decals.clear(); particles.clear(); }
        if (state == FREEZE && ns == LIVE) { PlayPool(S.roundStart, 0.8f); buyOpen = false; CaptureMouse(true); }
        if (ns == ROUNDEND) { gLastWinner = win; if (win >= 0) PlayPool(win == A[gMe].team ? S.win : S.lose, 0.8f); }
    }
    state = ns; stTimer = stT; roundTime = rT; scoreT = sT; scoreCT = sC; endMsg = em;

    // бомба
    if (planted && !bomb.planted) { PlayPool(S.planted, 0.9f); bomb.beepT = 0.0f; }
    if (exploded && !bomb.exploded) {
        bomb.explT = 0.0f; bomb.pos = bp;
        SpawnParticles(bp, 120, Col(255, 150, 40), 16.0f, 0.5f, 1.8f);
        SpawnParticles(bp, 80, Col(70, 60, 55), 9.0f, 0.7f, 2.5f);
        PlayPool(S.explode, 1.0f);
    }
    bomb.planted = planted; bomb.exploded = exploded;
    if (planted || exploded) { bomb.pos = bp; bomb.timer = bt; bomb.defuse = bd; }
    else { bomb.defuse = 0.0f; bomb.explT = 0.0f; }

    if (gMode == GM_CTF) for (int t = 0; t < 2; t++) { gFlag[t].carrier = fs[t].car; gFlag[t].atHome = fs[t].home; gFlag[t].pos = Vector3{ fs[t].x, 0.0f, fs[t].z }; }

    // игроки
    for (int i = 0; i < 8; i++) {
        Actor& a = A[i]; const AS& q = as[i];
        bool wasAlive = a.alive;
        bool human = (q.fl & 2) != 0;
        a.team = (i < 4) ? TERRO : CT;
        a.alive = (q.fl & 1) != 0;
        a.defusing = (q.fl & 4) != 0;
        if (q.fl & 8) a.flashT = 0.05f;
        a.hp = q.hp; a.armor = q.ar;
        a.cur = (q.cur < NUM_W) ? q.cur : W_GLOCK; a.pri = q.pri; a.sec = (q.sec < NUM_W) ? q.sec : W_GLOCK;
        a.carry = q.carry; a.kills = q.kills; a.deaths = q.deaths;
        if (human != a.human) { a.human = human; a.name = ActorName(i); }
        Vector3 hp3 = { q.x, q.y, q.z };
        if (i != gMe) {
            gTgt[i].pos = hp3; gTgt[i].yaw = q.yaw; a.pitch = q.pitch;
            if (!gTgt[i].valid || (!wasAlive && a.alive) || Vector3Distance(a.pos, hp3) > 6.0f) { a.pos = hp3; a.yaw = q.yaw; }
            gTgt[i].valid = true;
        } else {
            float err = Vector3Distance(a.pos, hp3);
            if (!gTgt[i].valid || (!wasAlive && a.alive) || err > 4.0f) { a.pos = hp3; a.vy = 0.0f; a.pitch = 0.0f; }
            else if (err > 1.2f) a.pos = Vector3Lerp(a.pos, hp3, 0.3f);
            gTgt[i].valid = true;
        }
        if (wasAlive && !a.alive) { if (i == gMe) PlayPool(S.death, 0.9f); else PlayAt(S.death, a.pos, 0.9f, 1.0f, 70.0f); }
    }
    {   // свои данные: деньги, патроны, перезарядка...
        Actor& me = A[gMe];
        if (money > me.money && money - me.money < 5000 && me.money > 0) popups.push_back({ money - me.money, 2.2f });
        if (money < me.money && buyOpen) PlayPool(S.buy, 0.8f);
        me.money = money; me.mag[me.cur] = mg; me.res[me.cur] = rs;
        me.reload = rel; me.rph = rph; me.recoil = rec; me.buyT = buyT; me.respawnT = respT; me.plantProg = plantP;
        me.jumpSlow = jSlow; me.jumpCd = jCd;
    }

    // события
    for (const NetEv& e : evs) {
        switch (e.type) {
            case EV_SHOT: {
                int sh = e.a, wid = e.b;
                if (sh >= 8 || wid >= NUM_W) break;
                if (sh == gMe) { if (wid == W_KNIFE) knifeT = 1.0f; else { muzzleT = 0.05f; gunKick = 1.0f; } PlayShot(wid, A[sh].pos, true); }
                else { PlayShot(wid, A[sh].pos, false); A[sh].flashT = 0.05f; }
            } break;
            case EV_TRACE: {
                if (e.a >= 8) break;
                Vector3 end = { e.x, e.y, e.z };
                Vector3 org = Eye(A[e.a]);
                Vector3 dir = Vector3Normalize(Vector3Subtract(end, org));
                Vector3 mz = Vector3Add(org, Vector3Scale(dir, 0.6f)); mz.y -= 0.12f;
                tracers.push_back({ mz, end, 0.06f });
                if (e.b) {
                    decals.push_back({ Vector3Add(end, Vector3{ 0, 0.02f, 0 }), 20.0f });
                    SpawnParticles(end, 4, Col(190, 170, 130), 2.5f, 0.05f, 0.5f);
                    PlayAt(S.impact, end, 0.4f, RandR(0.8f, 1.2f), 45.0f);
                }
            } break;
            case EV_HURT: {
                if (e.a >= 8) break;
                if (e.a == gMe) { hurtT = 0.35f; PlayPool(S.hurt, 0.8f); }
                if (e.b == gMe) { hitT = 0.25f; if (e.c) PlayPool(S.headshot, 0.7f); else PlayPool(S.hit, 0.6f); }
                SpawnParticles(Vector3Add(A[e.a].pos, Vector3{ 0, 1.2f, 0 }), 5, Col(150, 20, 20), 3.0f, 0.07f, 0.6f);
            } break;
            case EV_FEED: Feed(e.s); break;
            case EV_BANNER: banner = e.s; bannerT = e.x; break;
            default: break;
        }
    }
}

static void NetClientPacket(const unsigned char* d, int n, const NetAddr& from) {
    NR r(d, n);
    if (r.u8() != 'S' || r.u8() != 'S' || r.u8() != NET_VER) return;
    int type = r.u8();
    if (type == PK_ANNOUNCE) {
        int mode = r.u8(), humans = r.u8(), inm = r.u8();
        if (!r.ok) return;
        for (FoundHost& f : gFound) if (f.addr == from) { f.mode = mode; f.humans = humans; f.inMatch = inm != 0; f.last = gNetClock; return; }
        FoundHost f; f.addr = from; f.mode = mode; f.humans = humans; f.inMatch = inm != 0; f.last = gNetClock;
        gFound.push_back(f);
        return;
    }
    if (gCliState == 0 || !(from == gHostAddr)) return;      // остальное - только от нашего хоста
    gCliLastRx = gNetClock;
    if (type == PK_WELCOME) {
        int slot = r.u8(), mode = r.u8(); r.u8(); int mask = r.u8();
        if (!r.ok || slot < 0 || slot > 7) return;
        gMe = slot; gMode = mode; gLobMode = mode; gLobMask = mask;
        if (gCliState < 2) gCliState = 2;
    } else if (type == PK_REJECT) {
        NetClientLeave("Game is full");
    } else if (type == PK_LOBBY) {
        int mode = r.u8(), mask = r.u8();
        if (r.ok) { gLobMode = mode; gLobMask = mask; }
    } else if (type == PK_SNAP) {
        if (gCliState >= 2) {
            if (gCliState == 2) NetClientEnterGame();
            NetClientApply(r);
        }
    } else if (type == PK_LEAVE) {
        NetClientLeave("The host closed the game");
    }
}

static void NetClientSendInput() {
    NW w; w.header(PK_INPUT);
    w.u8((int)lroundf(Clamp(gCliIn.mx, -1.0f, 1.0f) * 127.0f));
    w.u8((int)lroundf(Clamp(gCliIn.mz, -1.0f, 1.0f) * 127.0f));
    w.f32(gCliIn.yaw); w.f32(gCliIn.pitch);
    w.u8((gCliIn.fire ? 1 : 0) | (gCliIn.scope ? 2 : 0) | (gCliIn.walk ? 4 : 0) | (gCliIn.use ? 8 : 0));
    w.u8(cJ); w.u8(cR); w.u8(cF); w.u8(cW); w.u8(cWV); w.u8(cB); w.u8(cBV);
    NetSend(gHostAddr, w.b, w.n);
}

static void NetClientTick(float dt) {
    unsigned char buf[1500]; NetAddr from;
    for (int k = 0; k < 128; k++) { int n = NetRecv(buf, sizeof(buf), from); if (n < 0) break; NetClientPacket(buf, n, from); if (!gNetClient) return; }
    if (gCliState == 0) {
        for (size_t i = 0; i < gFound.size();) { if (gNetClock - gFound[i].last > 3.5) gFound.erase(gFound.begin() + i); else i++; }
        return;
    }
    if (gCliState == 1) {
        gCliJoinT -= dt;
        if (gCliJoinT <= 0.0f) { gCliJoinT = 0.4f; NW w; w.header(PK_JOIN); w.u8(0); NetSend(gHostAddr, w.b, w.n); }
        if (gNetClock - gCliJoinStart > 6.0) NetClientLeave("Could not connect to the host");
        return;
    }
    gCliInT -= dt;
    if (gCliInT <= 0.0f) { gCliInT = (gCliState == 3) ? (1.0f / 30.0f) : 0.25f; NetClientSendInput(); }
    if (gNetClock - gCliLastRx > 5.0) NetClientLeave("Connection to the host lost");
}

static void NetTick(float dt) {
    if (!gNetHost && !gNetClient) return;
    gNetClock += dt;
    if (gNetHost) NetHostTick(dt); else NetClientTick(dt);
}

// кадр клиента в игре: хост считает мир, клиент показывает снимок и предсказывает своё движение
static void UpdateClientGame(float dt) {
    TickEffects(dt);
    if (state == FREEZE || state == LIVE) stTimer -= dt;
    if (state == LIVE) {
        if (bomb.planted && !bomb.exploded) {
            bomb.timer -= dt;
            bomb.beepT -= dt;
            if (bomb.beepT <= 0.0f && bomb.timer > 0.0f) {
                float k = Clamp(bomb.timer / 40.0f, 0.0f, 1.0f);
                bomb.beepT = 0.12f + 0.9f * k * k;
                bomb.blinkT = 0.12f;
                PlayAt(S.beep, bomb.pos, 0.9f, 1.0f, 200.0f);
            }
        } else if (!bomb.planted) roundTime -= dt;
    }
    bomb.blinkT = std::max(0.0f, bomb.blinkT - dt);
    if (bomb.exploded) bomb.explT += dt;
    for (int i = 0; i < 8; i++) {
        if (i == gMe) continue;
        Actor& a = A[i];
        a.flashT = std::max(0.0f, a.flashT - dt);
        if (!gTgt[i].valid || !a.alive) continue;
        Vector3 before = a.pos;
        a.pos = Vector3Lerp(a.pos, gTgt[i].pos, 1.0f - expf(-dt * 16.0f));
        a.yaw = TurnToward(a.yaw, gTgt[i].yaw, dt * 14.0f);
        float mv = Vector2Distance(Vector2{ before.x, before.z }, Vector2{ a.pos.x, a.pos.z });
        a.anim += mv * 2.4f;
        a.stepT += mv;
        if (a.stepT > 2.2f) { a.stepT = 0.0f; PlayAt(S.step, a.pos, 0.5f, RandR(0.85f, 1.1f), 30.0f); }
    }
    UpdatePlayer(dt);
}

